/*
 * Part 107 Flight Deck: question bank.
 *
 * 250 original practice questions. To edit a question, change its text below.
 * To add one, copy an entry, give it the next unused id, and keep exactly one
 * correct `answer` plus three `distractors` (the app shuffles the four choices).
 * `category` must be one of the seven subjects listed in CATEGORIES.
 */
window.P107 = window.P107 || {};
window.P107.CATEGORIES = ["Regulations", "Airspace & Charts", "Weather", "Airport & Radio", "Performance & Loading", "ADM & Human Factors", "Operations & Safety"];
window.P107.DIFFICULTIES = ["Foundation", "Applied", "Scenario"];
window.P107.QUESTIONS = [
  {"id": 1, "category": "Regulations", "difficulty": "Foundation", "question": "Who is directly responsible for and the final authority over a Part 107 small UAS operation?", "answer": "The designated remote pilot in command (remote PIC).", "distractors": ["The registered owner of the small UAS is always the final authority over the operation.", "The person manipulating the flight controls at launch is always the final authority over the operation.", "The visual observer assigned to scan for traffic is the final authority over the operation."], "explanation": "The remote PIC must be designated before or during the flight and is responsible for regulatory compliance and safe operation.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.19", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 2, "category": "Regulations", "difficulty": "Foundation", "question": "What is the maximum total takeoff weight for an aircraft operated as a “small unmanned aircraft” under Part 107?", "answer": "Less than 55 pounds, including everything onboard or attached.", "distractors": ["The aircraft may weigh 55 pounds or less, including everything onboard or attached.", "The aircraft must weigh less than 55 pounds before payloads and attachments are added.", "The aircraft may weigh less than 75 pounds, including everything onboard or attached."], "explanation": "The aircraft, payload, and attachments together must remain below 55 pounds unless another regulatory path applies.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area I, Task A — General", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 3, "category": "Regulations", "difficulty": "Foundation", "question": "How old must an applicant be to qualify for a Remote Pilot Certificate with a small UAS rating?", "answer": "At least 16 years old.", "distractors": ["An applicant must be at least 14 years old.", "An applicant must be at least 18 years old.", "An applicant must be at least 21 years old."], "explanation": "Eligibility also includes English-language ability, medical fitness for safe operation, and demonstrated aeronautical knowledge.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.61", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 4, "category": "Regulations", "difficulty": "Applied", "question": "May a person without a Remote Pilot Certificate manipulate the controls during a Part 107 flight?", "answer": "Yes—under direct supervision of a remote PIC who can immediately take direct control.", "distractors": ["No; every person who manipulates the controls must hold a Remote Pilot Certificate.", "Yes, provided a visual observer monitors the flight, even if the remote PIC cannot immediately take control.", "Yes, but only while the aircraft remains in Class G airspace."], "explanation": "The certificated remote PIC remains responsible and must be able to take over without delay.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.12", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 5, "category": "Regulations", "difficulty": "Foundation", "question": "Within what period must a remote pilot satisfy the aeronautical knowledge recency requirement?", "answer": "Within the previous 24 calendar months.", "distractors": ["The remote pilot must meet the recency requirement within the previous 12 calendar months.", "The remote pilot must meet the recency requirement within the preceding 24 months measured to the exact day.", "The remote pilot must meet the recency requirement within the previous 36 calendar months."], "explanation": "The requirement can be met through an applicable initial knowledge test or FAA-accepted recurrent training.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.65", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 6, "category": "Regulations", "difficulty": "Scenario", "question": "A Part 107 operation causes a serious injury. How soon must the remote PIC report the safety event to the FAA?", "answer": "No later than 10 calendar days after the operation.", "distractors": ["The event must be reported within 24 hours after the operation.", "The event must be reported no later than 5 calendar days after the operation.", "The event must be reported no later than 30 calendar days after the operation."], "explanation": "The reporting rule covers serious injury, loss of consciousness, and qualifying property damage.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.9", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 7, "category": "Regulations", "difficulty": "Applied", "question": "A drone damages someone else’s fence, and repairs cost $600. Does the Part 107 FAA reporting threshold apply?", "answer": "Yes, assuming the operation caused the damage.", "distractors": ["No; property damage is reportable only when repair cost exceeds $1,000.", "No; property damage is reportable only when the damaged property is a total loss.", "No; damage to a fence is excluded unless someone also suffers a bodily injury."], "explanation": "Damage to property other than the small UAS is reportable when repair cost or fair-market value in a total loss exceeds $500.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.9(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 8, "category": "Regulations", "difficulty": "Foundation", "question": "What is the maximum groundspeed allowed under standard Part 107 operating limits?", "answer": "87 knots, or 100 miles per hour.", "distractors": ["The maximum groundspeed is 87 miles per hour, or approximately 76 knots.", "The maximum groundspeed is 100 knots, or approximately 115 miles per hour.", "The maximum groundspeed is 120 knots, or approximately 138 miles per hour."], "explanation": "This is groundspeed—not indicated airspeed—and exceeding it requires an applicable waiver.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.51(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 9, "category": "Regulations", "difficulty": "Applied", "question": "When may a Part 107 drone fly higher than 400 feet above ground level without a waiver?", "answer": "When it stays within 400 feet of a structure and no more than 400 feet above that structure’s uppermost limit.", "distractors": ["The drone may exceed 400 feet AGL whenever it remains within 1,000 feet horizontally of a structure.", "The drone may fly up to 500 feet above a structure when it remains directly over that structure.", "The drone may fly up to 400 feet above any structure on the property when the property owner gives permission."], "explanation": "Both the horizontal radius and the height-above-structure conditions must be met.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.51(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 10, "category": "Regulations", "difficulty": "Foundation", "question": "What minimum flight visibility is required at the control station under standard Part 107 limits?", "answer": "At least 3 statute miles.", "distractors": ["At least 1 statute mile of flight visibility is required at the control station.", "At least 3 nautical miles of flight visibility is required at the control station.", "At least 5 statute miles of flight visibility is required at the control station."], "explanation": "Visibility is evaluated from the control station using the regulation’s day or night definition.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.51(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 11, "category": "Regulations", "difficulty": "Foundation", "question": "What are the standard Part 107 cloud-clearance minimums?", "answer": "At least 500 feet below and 2,000 feet horizontally from clouds.", "distractors": ["The aircraft must remain at least 1,000 feet below and 2,000 feet horizontally from clouds.", "The aircraft must remain at least 500 feet below and 1,000 feet horizontally from clouds.", "The aircraft need only remain clear of clouds while the remote PIC maintains visual line of sight."], "explanation": "Both clearances apply unless the operation is conducted under an applicable waiver.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.51(d)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 12, "category": "Regulations", "difficulty": "Applied", "question": "What two core conditions allow routine Part 107 operations at night?", "answer": "The remote PIC has completed qualifying updated knowledge testing or training, and the aircraft has anti-collision lighting visible for at least 3 statute miles.", "distractors": ["The remote PIC must hold a current certificate, and the aircraft must display steady position lights visible for 3 statute miles.", "The remote PIC must complete updated training, and the aircraft must carry a steady white light visible for 1 statute mile.", "A visual observer must be used, and the aircraft must carry a flashing light visible for 5 statute miles."], "explanation": "The light must flash fast enough to avoid collision; intensity may be reduced for safety but the light may not be extinguished.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.29(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 13, "category": "Regulations", "difficulty": "Scenario", "question": "Anti-collision lighting creates glare that makes a night operation less safe. What may the remote PIC do?", "answer": "Reduce the light’s intensity, but not extinguish it, if doing so is in the interest of safety.", "distractors": ["The remote PIC may extinguish the anti-collision light whenever glare interferes with the camera image.", "The remote PIC must maintain full light intensity and may not reduce it for any reason during flight.", "The remote PIC may cover the anti-collision light while the aircraft remains within visual line of sight."], "explanation": "The rule permits a safety-based reduction while preserving active anti-collision lighting.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.29(a)(2)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 14, "category": "Regulations", "difficulty": "Applied", "question": "What vision aid is permitted while maintaining required visual line of sight?", "answer": "Corrective lenses; binoculars or similar vision-enhancing devices do not satisfy continuous VLOS.", "distractors": ["Binoculars may be used continuously as the primary means of maintaining visual line of sight.", "First-person-view goggles alone satisfy visual line of sight when the video link is reliable.", "A telescope operated by the visual observer satisfies continuous visual line of sight."], "explanation": "The crew must be able to see the aircraft throughout flight with unaided vision other than corrective lenses.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.31", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 15, "category": "Regulations", "difficulty": "Scenario", "question": "Can one person act as remote PIC for two drones operating at the same time under standard Part 107 rules?", "answer": "No.", "distractors": ["Yes, if both drones remain within the remote PIC's visual line of sight.", "Yes, if one drone follows a fully automated flight plan.", "Yes, if one of the drones weighs 0.55 pounds or less."], "explanation": "A person may not manipulate controls, act as remote PIC, or serve as visual observer for more than one operation at a time.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.35", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 16, "category": "Regulations", "difficulty": "Foundation", "question": "Which aircraft has right of way in an encounter: a small UAS or any manned aircraft?", "answer": "The manned aircraft; the small UAS must yield and remain well clear.", "distractors": ["The small UAS has right of way whenever it remains below 400 feet AGL.", "Whichever aircraft reaches the conflict point first has right of way.", "The aircraft approaching from the left always has right of way, regardless of aircraft type."], "explanation": "The small UAS may not pass over, under, or ahead of the other aircraft unless well clear.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.37", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 17, "category": "Regulations", "difficulty": "Applied", "question": "May a remote pilot drop an object from a drone during a Part 107 operation?", "answer": "Only if doing so does not create an undue hazard to people or property.", "distractors": ["No object may ever be released from a small UAS during a Part 107 operation.", "An object may be dropped only over an unpopulated area, regardless of the hazard it creates.", "An object may be dropped whenever the property owner beneath the flight gives permission."], "explanation": "Part 107 prohibits hazardous dropping, not every release of an object.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.23(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 18, "category": "Regulations", "difficulty": "Scenario", "question": "During an in-flight emergency requiring immediate action, may the remote PIC deviate from Part 107?", "answer": "Yes, only to the extent necessary to meet the emergency.", "distractors": ["No; deviation is prohibited unless the remote PIC already holds a waiver for the affected rule.", "Yes; any Part 107 rule may be disregarded for the remainder of the mission once an emergency begins.", "Yes, but only after the remote PIC receives specific approval from air traffic control."], "explanation": "A written report is required only if the FAA Administrator requests one.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.21", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 19, "category": "Regulations", "difficulty": "Applied", "question": "What must a waiver application demonstrate?", "answer": "That the proposed operation can be conducted safely under the requested waiver’s terms.", "distractors": ["The application must demonstrate that the operation will provide a substantial economic or public benefit.", "The application must demonstrate that the remote PIC has at least 100 hours of flight experience and liability insurance.", "The application must demonstrate only that the operation will remain in Class G airspace and avoid people."], "explanation": "The request needs a complete operational description and a safety justification; approval is not automatic.", "source": {"label": "FAA Part 107 Waivers", "reference": "§§ 107.200–107.205", "url": "https://www.faa.gov/uas/commercial_operators/part_107_waivers"}},
  {"id": 20, "category": "Regulations", "difficulty": "Foundation", "question": "What are the three normal ways a drone pilot can comply with Remote ID?", "answer": "Use a Standard Remote ID drone, attach a Remote ID broadcast module, or fly a non-equipped drone inside a FRIA under its conditions.", "distractors": ["Use ADS-B Out, remain below 400 feet AGL, or obtain a LAANC authorization.", "Fly only in Class G airspace, use a visual observer, or keep the drone within 500 feet of the pilot.", "File a NOTAM, monitor the local CTAF, or carry the aircraft's registration certificate."], "explanation": "Most drones that must be registered must also comply with Remote ID; each path has its own operating conditions.", "source": {"label": "FAA Remote ID", "reference": "Remote ID compliance methods", "url": "https://www.faa.gov/uas/getting_started/remote_id"}},
  {"id": 21, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "Which controlled-airspace classes generally require prior ATC authorization for Part 107 operations?", "answer": "Class B, C, and D, plus Class E surface areas designated for an airport.", "distractors": ["All Class E airspace, including areas beginning at 700 or 1,200 feet AGL, requires prior authorization.", "Only Class B and Class C airspace require prior authorization under Part 107.", "Class B, Class C, Class D, and all Class G airspace within five miles of an airport require prior authorization."], "explanation": "The authorization requirement applies within the lateral boundaries of those controlled surface areas.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.41", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 22, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What airspace class normally begins at the surface and extends to 10,000 feet MSL around the nation’s busiest airports?", "answer": "Class B airspace.", "distractors": ["Class C airspace normally begins at the surface and extends to 10,000 feet MSL around the nation's busiest airports.", "Class D airspace normally begins at the surface and extends to 10,000 feet MSL around the nation's busiest airports.", "Class E airspace normally begins at the surface and extends to 10,000 feet MSL around the nation's busiest airports."], "explanation": "Its shape and floors vary by location and are charted in layers, often compared to an upside-down wedding cake.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class B Airspace", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 23, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What chart color and line style depict the outer boundaries of Class B airspace on a sectional?", "answer": "Solid blue lines.", "distractors": ["Class B outer boundaries are depicted with dashed blue lines.", "Class B outer boundaries are depicted with solid magenta lines.", "Class B outer boundaries are depicted with shaded blue vignettes."], "explanation": "Blue floor-and-ceiling numbers inside the boundary identify the vertical limits in hundreds of feet MSL.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Aeronautical charts", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 24, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What chart color and line style depict Class C airspace?", "answer": "Solid magenta lines.", "distractors": ["Class C airspace is depicted with solid blue lines.", "Class C airspace is depicted with dashed magenta lines.", "Class C airspace is depicted with dashed blue lines."], "explanation": "Class C typically has a surface core and an outer shelf, but pilots must read the charted limits for the location.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class C Airspace", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 25, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What sectional-chart symbol normally marks a Class D surface boundary?", "answer": "A dashed blue line.", "distractors": ["A Class D surface boundary is normally marked by a dashed magenta line.", "A Class D surface boundary is normally marked by a solid blue line.", "A Class D surface boundary is normally marked by a shaded magenta vignette."], "explanation": "The top is commonly shown by a boxed altitude in hundreds of feet MSL, but charted exceptions must be checked.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class D Airspace", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 26, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What does a dashed magenta boundary on a sectional normally indicate?", "answer": "Class E airspace beginning at the surface.", "distractors": ["A dashed magenta boundary normally indicates Class D airspace beginning at the surface.", "A dashed magenta boundary normally indicates the outer shelf of Class C airspace.", "A dashed magenta boundary normally indicates Class E airspace beginning at 700 feet AGL."], "explanation": "If it is designated for an airport, a Part 107 operation inside its lateral boundary requires prior ATC authorization.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class E Airspace", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 27, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What does a shaded magenta vignette around an airport indicate about the floor of Class E airspace?", "answer": "Class E begins at 700 feet AGL inside the vignette.", "distractors": ["Class E airspace begins at 1,200 feet AGL inside a shaded magenta vignette.", "Class E airspace begins at the surface inside a shaded magenta vignette.", "Class E airspace begins at 700 feet MSL inside a shaded magenta vignette."], "explanation": "Below that floor, the airspace is generally Class G unless another surface area is charted.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class E floor depictions", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 28, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What does a shaded blue vignette indicate about the floor of Class E airspace?", "answer": "Class E begins at 1,200 feet AGL inside the vignette.", "distractors": ["Class E airspace begins at 700 feet AGL inside a shaded blue vignette.", "Class E airspace begins at 1,200 feet MSL inside a shaded blue vignette.", "Class E airspace begins at 14,500 feet MSL inside a shaded blue vignette."], "explanation": "Outside lower Class E transition areas, 1,200 feet AGL is a common Class E floor.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class E floor depictions", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 29, "category": "Airspace & Charts", "difficulty": "Scenario", "question": "Your site is in Class G at the surface, with Class E beginning at 700 feet AGL. You plan to remain at 300 feet AGL. Is § 107.41 ATC authorization required solely because of the Class E above?", "answer": "No.", "distractors": ["Yes; the presence of any Class E airspace above the site triggers the authorization requirement.", "Yes; authorization is required above 200 feet AGL whenever Class E airspace is within 500 feet vertically.", "Yes; every small UAS operation within five miles of an airport requires prior authorization."], "explanation": "The aircraft remains in Class G; other restrictions, airspace notices, and Part 107 rules still apply.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.41", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 30, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What is LAANC used for by Part 107 pilots?", "answer": "Requesting near-real-time or further-coordinated authorization to operate in eligible controlled airspace.", "distractors": ["LAANC is used to obtain an official aviation weather briefing for a small UAS mission.", "LAANC is used to request a waiver from standard Part 107 operating limitations.", "LAANC is used to register a small UAS and activate its Remote ID equipment."], "explanation": "Approval limits do not replace the need to comply with every other applicable rule and authorization condition.", "source": {"label": "FAA Part 107 Airspace Authorizations", "reference": "LAANC authorization guidance", "url": "https://www.faa.gov/uas/commercial_operators/part_107_airspace_authorizations"}},
  {"id": 31, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "May you enter a prohibited area with a small UAS merely because you are below 400 feet AGL?", "answer": "No.", "distractors": ["Yes; flights below 400 feet AGL are exempt from prohibited-area restrictions.", "Yes; the landowner's permission permits entry into the prohibited area at low altitude.", "Yes; entry is permitted whenever no active Temporary Flight Restriction appears over the area."], "explanation": "Operations in prohibited or restricted areas require permission from the using or controlling agency, as appropriate.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.45", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 32, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What is the key operational difference between a restricted area and a military operations area (MOA)?", "answer": "A Part 107 pilot may not enter a restricted area without agency permission. A MOA is nonregulatory; it does not prohibit VFR entry, but pilots should check its status and use extreme caution.", "distractors": ["A restricted area is always open to VFR traffic without permission, while an MOA prohibits entry whenever active.", "Both restricted areas and MOAs prohibit all civilian entry whenever their boundaries appear on a chart.", "An MOA always requires prior ATC authorization, while an active restricted area may be entered below 400 feet AGL."], "explanation": "Section 107.45 does not create an inactive-area exception for restricted airspace; MOA activity can change frequently and may involve fast military traffic.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM §§ 3-4-3 and 3-4-5; 14 CFR § 107.45", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 33, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What is a Temporary Flight Restriction (TFR)?", "answer": "A short-term restriction issued by NOTAM for a defined area, time, and purpose.", "distractors": ["A TFR is permanent special-use airspace established around every major airport.", "A TFR is an advisory area that recommends caution but creates no operating restriction.", "A TFR is a standing 30-nautical-mile restriction automatically active around every towered airport."], "explanation": "Common causes include disasters, major events, VIP movement, wildfire response, or space operations; pilots must check current notices.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area II — Flight restrictions and NOTAMs", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 34, "category": "Airspace & Charts", "difficulty": "Applied", "question": "On a sectional, what do two numbers beside an obstacle—one in parentheses—normally represent?", "answer": "The top number is the obstacle elevation MSL; the parenthetical number is its height AGL.", "distractors": ["The top number is the obstacle's height AGL, and the parenthetical number is its elevation MSL.", "The top number is the obstacle-top elevation MSL, and the parenthetical number is the obstacle-base elevation MSL.", "The top number is the obstacle's height above the airport, and the parenthetical number is its distance from the charted airport."], "explanation": "Both matter: MSL supports chart comparison, while AGL shows the structure’s height above local terrain.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 11 — Obstructions", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 35, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What does a sectional chart’s Maximum Elevation Figure (MEF) communicate?", "answer": "The elevation of the highest terrain or obstacle in that quadrangle, with charting allowance, expressed in hundreds of feet MSL.", "distractors": ["The MEF is a guaranteed minimum safe altitude that provides regulatory obstacle clearance throughout the quadrangle.", "The MEF is the elevation AGL of the highest airport located within the quadrangle.", "The MEF is the height of the tallest man-made obstruction and excludes terrain and charting allowance."], "explanation": "MEF is a planning aid—not a guarantee of obstacle clearance or a substitute for local reconnaissance.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Sectional chart features", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 36, "category": "Airspace & Charts", "difficulty": "Scenario", "question": "A sectional shows a tower as 1,549 MSL (500 AGL). What is the approximate ground elevation at the tower?", "answer": "About 1,049 feet MSL.", "distractors": ["The approximate ground elevation is 500 feet MSL.", "The approximate ground elevation is 1,549 feet MSL.", "The approximate ground elevation is 2,049 feet MSL."], "explanation": "Subtract the obstacle height AGL from its top elevation MSL: 1,549 − 500 = 1,049.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 11 — Obstruction elevations", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 37, "category": "Weather", "difficulty": "Foundation", "question": "What does METAR provide?", "answer": "A routine observation of current surface weather at an airport or reporting station.", "distractors": ["A METAR provides a forecast of airport weather for a stated future valid period.", "A METAR provides a pilot's in-flight report of turbulence, icing, and cloud tops.", "A METAR provides time-sensitive notices about airport closures and airspace restrictions."], "explanation": "A SPECI is a special, unscheduled report issued when significant weather criteria are met.", "source": {"label": "NWS METAR/TAF Key", "reference": "METAR message type", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 38, "category": "Weather", "difficulty": "Foundation", "question": "What does TAF provide?", "answer": "A coded forecast of weather expected near an airport during a stated valid period.", "distractors": ["A TAF provides a routine observation of current surface weather at an airport.", "A TAF provides a nationwide forecast of en route turbulence and icing hazards.", "A TAF provides an individual pilot report of weather encountered during flight."], "explanation": "Always verify the issue time and valid period; all TAF times are in UTC (Zulu).", "source": {"label": "NWS METAR/TAF Key", "reference": "TAF message type and valid period", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 39, "category": "Weather", "difficulty": "Applied", "question": "Decode the METAR wind group “22015G25KT.”", "answer": "Wind from 220° true at 15 knots, gusting to 25 knots.", "distractors": ["Wind is blowing toward 220 degrees true at 15 knots, gusting to 25 knots.", "Wind is from 220 degrees true at 25 knots, gusting to 15 knots.", "Wind is from 220 degrees magnetic at 15 knots, gusting to 25 knots."], "explanation": "METAR wind direction is referenced to true north; the G value is the peak gust speed.", "source": {"label": "NWS METAR/TAF Key", "reference": "Wind group", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 40, "category": "Weather", "difficulty": "Applied", "question": "What does “00000KT” mean in a METAR?", "answer": "Calm wind.", "distractors": ["The wind direction is variable at 5 knots.", "The wind is from true north at 10 knots.", "The wind direction is unavailable, but gusts are expected to reach 10 knots."], "explanation": "Variable direction is coded VRB, while calm is reported as all zeros.", "source": {"label": "NWS METAR/TAF Key", "reference": "Wind group", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 41, "category": "Weather", "difficulty": "Applied", "question": "Decode “3/4SM” in a METAR.", "answer": "Three-quarters of a statute mile visibility.", "distractors": ["Visibility is 3.4 statute miles.", "Visibility is three-quarters of a nautical mile.", "Visibility is 3 statute miles with a 4-statute-mile directional variation."], "explanation": "Part 107 normally requires at least 3 statute miles of flight visibility from the control station.", "source": {"label": "NWS METAR/TAF Key", "reference": "Prevailing visibility", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 42, "category": "Weather", "difficulty": "Applied", "question": "Decode the cloud group “BKN015.”", "answer": "A broken cloud layer with a base 1,500 feet above ground level.", "distractors": ["A broken cloud layer has a base 15,000 feet AGL.", "A broken cloud layer has a base 1,500 feet MSL.", "An overcast cloud layer has a base 1,500 feet AGL."], "explanation": "BKN and OVC layers constitute a ceiling; the three digits give hundreds of feet AGL.", "source": {"label": "NWS METAR/TAF Key", "reference": "Sky condition group", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 43, "category": "Weather", "difficulty": "Foundation", "question": "Which reported sky conditions constitute a ceiling?", "answer": "The lowest broken (BKN), overcast (OVC), or vertical visibility (VV) layer.", "distractors": ["The lowest scattered, broken, or overcast layer constitutes the ceiling.", "The highest broken or overcast layer constitutes the ceiling.", "Any few or scattered layer constitutes the ceiling when visibility is below 3 statute miles."], "explanation": "Few and scattered layers are not ceilings, though they may still affect a mission.", "source": {"label": "NWS METAR/TAF Key", "reference": "Ceiling and sky cover", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 44, "category": "Weather", "difficulty": "Applied", "question": "Decode the temperature/dew-point group “18/16.”", "answer": "Temperature 18°C and dew point 16°C.", "distractors": ["The temperature is 18 degrees Celsius and the dew point is minus 16 degrees Celsius.", "The temperature is 16 degrees Celsius and the dew point is 18 degrees Celsius.", "The temperature is 18 degrees Fahrenheit and the dew point is 16 degrees Fahrenheit."], "explanation": "A small temperature–dew point spread indicates air near saturation and increased potential for fog or low cloud.", "source": {"label": "NWS METAR/TAF Key", "reference": "Temperature/dew-point group", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 45, "category": "Weather", "difficulty": "Applied", "question": "What does “A2992” mean in a METAR?", "answer": "Altimeter setting 29.92 inches of mercury.", "distractors": ["The reported atmospheric pressure is 2,992 hectopascals.", "The altimeter setting is 29.92 millibars.", "The reporting station's field elevation is 2,992 feet MSL."], "explanation": "The A prefix is followed by four digits representing inches of mercury to the hundredth.", "source": {"label": "NWS METAR/TAF Key", "reference": "Altimeter setting", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 46, "category": "Weather", "difficulty": "Foundation", "question": "What three ingredients are required for a thunderstorm to form?", "answer": "Moisture, unstable air, and a lifting action.", "distractors": ["A thunderstorm requires moisture, stable air, and a sustained sinking action.", "A thunderstorm requires dry air, atmospheric instability, and a lifting action.", "A thunderstorm requires moisture, a temperature inversion, and low-level wind shear."], "explanation": "Removing any one of the three prevents thunderstorm development.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Thunderstorm formation", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 47, "category": "Weather", "difficulty": "Scenario", "question": "A mature thunderstorm is near the site but no rain is falling at your launch point. What is the safest decision?", "answer": "Do not launch; remain well clear and wait for the hazard to pass.", "distractors": ["Launch because the site is safe until precipitation reaches the takeoff point.", "Launch below 200 feet AGL because thunderstorm hazards do not extend to that altitude.", "Launch after checking surface wind because visual line of sight is sufficient protection from the nearby storm."], "explanation": "Thunderstorms can produce lightning, hail, severe turbulence, gust fronts, and wind shear well beyond visible precipitation.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Thunderstorm hazards", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 48, "category": "Weather", "difficulty": "Foundation", "question": "How does stable air typically differ from unstable air?", "answer": "Stable air favors smooth conditions, stratiform clouds, and poorer visibility; unstable air favors turbulence, vertical clouds, showers, and generally better visibility outside precipitation.", "distractors": ["Stable air favors turbulence, cumuliform clouds, and good visibility, while unstable air favors smooth air, stratus, and haze.", "Stable air supports strong vertical currents and showers, while unstable air suppresses vertical motion.", "Stable air and unstable air produce the same cloud types and visibility; only surface wind differs."], "explanation": "Stability describes the atmosphere’s resistance to vertical motion.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Atmospheric stability", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 49, "category": "Weather", "difficulty": "Applied", "question": "What weather change is commonly associated with a passing cold front?", "answer": "A wind shift, temperature drop, pressure change, and potentially showery or convective weather.", "distractors": ["A passing cold front commonly brings a gradual temperature rise, steady pressure, and widespread stratiform weather.", "A passing cold front normally produces no wind shift, no pressure change, and clear skies throughout its passage.", "A passing cold front commonly brings warmer air, a rising dew point, and slowly developing fair-weather clouds."], "explanation": "Cold fronts lift warmer air rapidly, so their weather can be more abrupt than a typical warm front.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Fronts and air masses", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 50, "category": "Weather", "difficulty": "Applied", "question": "Why is a temperature inversion important to a drone pilot?", "answer": "It can trap haze, smoke, and moisture near the surface, reducing visibility despite otherwise calm conditions.", "distractors": ["A temperature inversion promotes vigorous vertical mixing and rapidly improves surface visibility.", "A temperature inversion guarantees strong, gusty surface winds that disperse smoke and moisture.", "A temperature inversion is a layer where temperature decreases unusually fast with altitude, creating strong instability."], "explanation": "An inversion is a layer in which temperature increases with altitude, creating strong stability.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Temperature inversions and visibility", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 51, "category": "Weather", "difficulty": "Scenario", "question": "Surface wind is light, but the forecast calls for a sharp change in wind speed and direction just above the trees. What hazard should concern you?", "answer": "Low-level wind shear.", "distractors": ["The primary concern is high density altitude caused by the wind direction change.", "The primary concern is radiation fog forming above the tree line.", "The primary concern is an altimeter-setting error caused by the stronger wind aloft."], "explanation": "A rapid wind change over a short distance can cause abrupt attitude, groundspeed, and control changes—especially near takeoff and landing.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Wind shear", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 52, "category": "Weather", "difficulty": "Applied", "question": "Which combination produces the highest density altitude?", "answer": "High elevation, high temperature, low pressure, and high humidity.", "distractors": ["The highest density altitude occurs with low elevation, low temperature, high pressure, and low humidity.", "The highest density altitude occurs with high elevation, very low temperature, high pressure, and dry air.", "The highest density altitude occurs at sea level with low temperature, high pressure, and low humidity."], "explanation": "High density altitude means lower air density, reducing propeller efficiency and aircraft performance.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Aircraft performance and density altitude", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 53, "category": "Weather", "difficulty": "Foundation", "question": "What conditions favor radiation fog?", "answer": "Clear skies, light wind, moist air, and nighttime surface cooling.", "distractors": ["Radiation fog is favored when warm, moist air moves over a colder surface in a moderate wind.", "Radiation fog is favored when moist, unstable air is forced rapidly up a mountain slope.", "Radiation fog is favored by overcast daylight conditions, dry air, and strong turbulent wind."], "explanation": "Strong wind tends to mix the air, while calm to light wind supports cooling and saturation near the surface.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Fog formation", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 54, "category": "Weather", "difficulty": "Applied", "question": "In a TAF, how does “FM” differ from “TEMPO”?", "answer": "FM starts a new prevailing condition at a specified time; TEMPO describes temporary fluctuations during a stated period.", "distractors": ["FM describes a brief fluctuation lasting less than one hour, while TEMPO starts a new prevailing condition.", "FM expresses only the probability of a change, while TEMPO marks a permanent change for the rest of the forecast.", "FM and TEMPO both indicate the same abrupt, lasting change in prevailing conditions."], "explanation": "A TEMPO condition is expected for less than one hour at a time and less than half of the indicated period in total.", "source": {"label": "NWS METAR/TAF Key", "reference": "TAF change groups", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 55, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What is the purpose of a Common Traffic Advisory Frequency (CTAF)?", "answer": "To let pilots exchange traffic information and position reports at or near an airport, especially when no tower is operating.", "distractors": ["CTAF is used to request an airspace authorization from air traffic control.", "CTAF is used to receive automated airport weather observations without pilot transmissions.", "CTAF is used by a controller to issue mandatory traffic sequencing at every non-towered airport."], "explanation": "Monitoring CTAF helps a remote crew build traffic awareness, but radio calls never replace visual scanning and yielding.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM § 4-1-9 — Traffic advisory practices", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_1.html"}},
  {"id": 56, "category": "Airport & Radio", "difficulty": "Applied", "question": "A runway is numbered 27. Approximately which magnetic direction does it point?", "answer": "270°, or west.", "distractors": ["Runway 27 points approximately 027 degrees magnetic, or northeast.", "Runway 27 points approximately 090 degrees magnetic, or east.", "Runway 27 points approximately 180 degrees magnetic, or south."], "explanation": "Runway numbers are the magnetic heading rounded to the nearest 10 degrees with the final zero omitted.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Airport operations — runway markings", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 57, "category": "Airport & Radio", "difficulty": "Foundation", "question": "Unless airport indicators or published information show otherwise, which direction do standard traffic-pattern turns use?", "answer": "Left turns.", "distractors": ["Standard traffic patterns use right turns unless published information shows otherwise.", "Standard traffic patterns alternate left and right turns on successive legs.", "Standard traffic patterns require turns toward the current surface wind."], "explanation": "Right traffic is identified by traffic-pattern indicators or chart information such as “RP” followed by a runway number.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Traffic patterns", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_3.html"}},
  {"id": 58, "category": "Airport & Radio", "difficulty": "Applied", "question": "Which end of a windsock points into the wind?", "answer": "The large, open end.", "distractors": ["The narrow, trailing end of the windsock points into the wind.", "Neither end points into the wind because a windsock indicates wind speed but not wind direction.", "The end nearest the active runway points into the wind regardless of the windsock's actual orientation."], "explanation": "The narrow end streams downwind, helping determine the wind direction and likely runway in use.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Visual indicators at airports", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_3.html"}},
  {"id": 59, "category": "Airport & Radio", "difficulty": "Applied", "question": "What does the small end of an airport tetrahedron indicate?", "answer": "The direction of landing and takeoff.", "distractors": ["The small end of the tetrahedron points into the wind and reports wind direction.", "The small end of the tetrahedron indicates the direction opposite to landing and takeoff.", "The small end of the tetrahedron indicates the preferred direction of ground taxi only."], "explanation": "A tetrahedron is not a wind indicator, and tower instructions supersede it when the tower is operating.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Landing direction indicator", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_3.html"}},
  {"id": 60, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What information can a segmented circle system provide?", "answer": "Wind direction, landing direction, runway alignment, and traffic-pattern direction.", "distractors": ["A segmented circle provides runway length, airport elevation, available fuel, and lighting intensity.", "A segmented circle provides controlled-airspace boundaries, radio frequencies, and cloud-clearance minimums.", "A segmented circle provides only wind speed and wind direction."], "explanation": "Its components help pilots interpret airport operations when a control tower is not operating.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Segmented circle system", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_3.html"}},
  {"id": 61, "category": "Airport & Radio", "difficulty": "Applied", "question": "What information should a concise self-announce broadcast at a non-towered airport include?", "answer": "The correct airport name, aircraft type and call sign, position and altitude as applicable, and intentions; repeat the airport name at the end.", "distractors": ["A useful self-announce call states the aircraft registration, Remote ID serial number, and pilot certificate number.", "A useful self-announce call states the airport elevation, runway length, and current altimeter setting.", "A useful self-announce call states the controller's name, assigned transponder code, and requested clearance."], "explanation": "Aircraft identification is essential; addressee, position, and intentions alone are incomplete.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM § 4-1-9 — Self-announce position and intentions", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_1.html"}},
  {"id": 62, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What do AWOS and ASOS provide?", "answer": "Automated surface weather observations.", "distractors": ["AWOS and ASOS provide air traffic control clearances and runway sequencing.", "AWOS and ASOS provide collision-avoidance advisories for aircraft in the traffic pattern.", "AWOS and ASOS provide LAANC approvals, NOTAM updates, and Remote ID status."], "explanation": "They can report wind, visibility, ceiling, temperature, dew point, and altimeter data depending on the system.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Aviation weather services", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 63, "category": "Airport & Radio", "difficulty": "Applied", "question": "What rotating-beacon colors identify a lighted civilian land airport?", "answer": "Alternating white and green.", "distractors": ["A lighted civilian land airport uses an alternating white-and-yellow rotating beacon.", "A lighted civilian land airport uses an alternating white-and-blue rotating beacon.", "A lighted civilian land airport uses an alternating green-and-yellow rotating beacon."], "explanation": "Beacon patterns help identify airport types at night or in reduced visibility.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Airport lighting and beacons", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 64, "category": "Airport & Radio", "difficulty": "Scenario", "question": "Your site is outside controlled airspace but directly under an airport’s traffic pattern. Is the operation automatically acceptable without ATC authorization?", "answer": "No. You must avoid interfering with airport operations and traffic patterns.", "distractors": ["Yes; being outside controlled airspace makes the operation automatically acceptable.", "Yes; remaining below 400 feet AGL removes the requirement to avoid the traffic pattern.", "Yes; monitoring the airport's CTAF permits the drone to operate directly beneath the traffic pattern."], "explanation": "Airspace authorization and safe airport-vicinity operation are separate requirements.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.43", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 65, "category": "Airport & Radio", "difficulty": "Foundation", "question": "Why must a remote pilot check NOTAMs before flight?", "answer": "They contain time-sensitive aeronautical information that may affect the operation, including closures, hazards, and flight restrictions.", "distractors": ["NOTAMs contain only permanent information that is already depicted on current aeronautical charts.", "NOTAMs contain long-range weather forecasts but do not address closures or airspace hazards.", "NOTAMs contain only the altitude limits available for automated airspace authorization."], "explanation": "A chart can be current yet still omit short-notice conditions announced by NOTAM.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area II — Sources for flight restrictions", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 66, "category": "Airport & Radio", "difficulty": "Scenario", "question": "A helicopter appears on short final toward a nearby pad while your drone is airborne. What should you do?", "answer": "Yield immediately, keep the drone well clear, and land or reposition safely as needed.", "distractors": ["Hold the drone in place because the helicopter must yield to traffic already airborne.", "Climb the drone above the traffic pattern so the helicopter can pass underneath.", "Continue the mission below 400 feet AGL after announcing the drone's position on CTAF."], "explanation": "The small UAS must yield to all aircraft, and the remote PIC may not interfere with heliport traffic patterns.", "source": {"label": "14 CFR Part 107", "reference": "§§ 107.37 and 107.43", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 67, "category": "Performance & Loading", "difficulty": "Foundation", "question": "What is center of gravity (CG)?", "answer": "The point at which the aircraft would balance if suspended.", "distractors": ["Center of gravity is the geometric center of the aircraft, regardless of component or payload weight.", "Center of gravity is the location of the aircraft's heaviest individual component.", "Center of gravity is the point where total lift acts and is always fixed by the airframe design."], "explanation": "Payload placement can move the CG and change stability, control authority, and power required.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Weight and balance", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 68, "category": "Performance & Loading", "difficulty": "Applied", "question": "How does high density altitude generally affect a small UAS?", "answer": "It reduces aerodynamic and propeller performance, often requiring more power for the same result.", "distractors": ["High density altitude increases propeller efficiency and reduces the power needed to hover.", "High density altitude has no effect on an electrically powered small UAS.", "High density altitude increases air density, improving climb rate and endurance."], "explanation": "Hot, high, humid, or low-pressure conditions can reduce lift, thrust, climb performance, and endurance.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Aircraft performance", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 69, "category": "Performance & Loading", "difficulty": "Foundation", "question": "What is the usual effect of adding weight to a small UAS?", "answer": "Higher power demand, reduced climb performance and endurance, and greater kinetic energy.", "distractors": ["Adding weight reduces power demand and normally increases flight endurance.", "Adding weight improves climb performance without changing kinetic energy.", "Adding weight affects only center of gravity and has no performance effect while total weight remains below 55 pounds."], "explanation": "The exact effect depends on the aircraft, but added mass never comes free; manufacturer limits still control.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 4 — Loading", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 70, "category": "Performance & Loading", "difficulty": "Applied", "question": "What must the remote PIC verify about an attached payload before flight?", "answer": "It is secure and does not adversely affect flight characteristics or controllability.", "distractors": ["The remote PIC need only verify that the payload remains attached and total aircraft weight is below 55 pounds.", "The remote PIC may disregard the payload's effect on control because flight-control software automatically compensates for it.", "The remote PIC must verify that the payload can be released in flight, even if the mission does not require a release."], "explanation": "The complete aircraft must also remain within its applicable weight and operating limits.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(e)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 71, "category": "Performance & Loading", "difficulty": "Applied", "question": "Why is an out-of-limit aft CG hazardous?", "answer": "It can reduce stability and make recovery from a disturbance more difficult.", "distractors": ["An aft center of gravity increases stability and makes recovery from a disturbance easier.", "An aft center of gravity affects only battery endurance and does not affect handling or stability.", "An aft center of gravity makes the aircraft nose-heavy and guarantees greater pitch-control authority."], "explanation": "CG limits are aircraft-specific; flight-control software cannot be assumed to compensate for an unsafe loading condition.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "CG effects and stability", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 72, "category": "Performance & Loading", "difficulty": "Scenario", "question": "A camera is mounted far forward and the drone hovers with a persistent rearward tilt. What is the best response?", "answer": "Land and correct the loading or mounting before continuing.", "distractors": ["Continue the flight because the flight controller's compensation proves the loading is acceptable.", "Increase groundspeed until aerodynamic forces level the aircraft.", "Recalibrate the compass while airborne to remove the rearward hover tilt."], "explanation": "A control system constantly compensating for poor balance wastes power and may have less authority left for wind or maneuvering.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 4 — Loading and performance", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 73, "category": "Performance & Loading", "difficulty": "Foundation", "question": "What happens to load factor as a level turn becomes steeper?", "answer": "Load factor increases.", "distractors": ["Load factor decreases as a level turn becomes steeper.", "Load factor remains at one regardless of bank angle during a level turn.", "Load factor becomes zero once the bank angle exceeds 45 degrees."], "explanation": "More total lift is required to support weight while also turning, which increases structural and performance demand.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Aerodynamics of flight — load factor", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 74, "category": "Performance & Loading", "difficulty": "Applied", "question": "How can cold weather affect lithium-based flight batteries?", "answer": "It can reduce available capacity and voltage performance, shortening endurance and increasing sag under load.", "distractors": ["Cold weather increases available battery capacity and reduces voltage sag under load.", "Cold weather has no effect on a lithium-based flight battery until the temperature reaches exactly 0 degrees Fahrenheit.", "Cold weather changes charging time but does not affect in-flight endurance or power delivery."], "explanation": "Follow manufacturer temperature guidance and use a larger landing reserve when conditions warrant.", "source": {"label": "FAA Safety Briefing — Cold Batteries", "reference": "Cold-weather battery capacity, resistance, and endurance", "url": "https://www.faa.gov/sites/faa.gov/files/NovDec2023.pdf"}},
  {"id": 75, "category": "Performance & Loading", "difficulty": "Scenario", "question": "One propeller has a small chip, but the aircraft still arms normally. Should the flight continue?", "answer": "No—replace or service the propeller according to manufacturer guidance before flight.", "distractors": ["Continue the flight because normal arming confirms that the chipped propeller is airworthy.", "Remove an equal amount of material from the opposite propeller to restore balance, then fly normally.", "Continue at low altitude because a small propeller chip matters only above 400 feet AGL."], "explanation": "Damage can create imbalance, vibration, loss of efficiency, or failure that may not appear during a brief idle check.", "source": {"label": "FAA AC 107-2A", "reference": "Maintenance and preflight inspection", "url": "https://www.faa.gov/regulations_policies/advisory_circulars/index.cfm/go/document.information/documentID/1038977"}},
  {"id": 76, "category": "Performance & Loading", "difficulty": "Scenario", "question": "You fly outbound with a strong tailwind. What hidden return-flight risk must you plan for?", "answer": "The return leg will face a headwind and may require much more time and battery energy.", "distractors": ["The return leg will also have a tailwind and should require less battery energy than the outbound leg.", "The wind's effects cancel over a round trip, so outbound battery use alone is sufficient for planning.", "The primary return-flight risk is loss of GPS reception caused by turning into the wind."], "explanation": "Plan energy using the least favorable leg, maintain reserves, and turn back early enough to land safely.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area III, Task B, UA.III.B.K1b — Wind and currents", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 77, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What is aeronautical decision-making (ADM)?", "answer": "A systematic approach to choosing the best action in response to a given set of circumstances.", "distractors": ["ADM is an immediate reflex response that avoids deliberate comparison of alternatives.", "ADM is the manufacturer-prescribed maintenance schedule for an aircraft.", "ADM is the air traffic control process used to separate aircraft in controlled airspace."], "explanation": "Good ADM identifies hazards, assesses risk, and selects controls before the situation becomes an emergency.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Chapter 2 — Aeronautical Decision-Making", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 78, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What four risk areas make up the PAVE checklist?", "answer": "Pilot, Aircraft, enVironment, and External pressures.", "distractors": ["PAVE stands for Plan, Airspace, Visibility, and Equipment.", "PAVE stands for Pilotage, Airport, Vehicle, and Emergency.", "PAVE stands for Performance, Altitude, Velocity, and Endurance."], "explanation": "PAVE helps organize a preflight risk assessment so one attractive mission goal does not hide a critical weakness.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "PAVE risk checklist", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 79, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What does the IMSAFE checklist evaluate?", "answer": "Illness, Medication, Stress, Alcohol, Fatigue, and Emotion.", "distractors": ["IMSAFE evaluates Instruments, Maintenance, Systems, Airspace, Fuel, and Environment.", "IMSAFE evaluates Identification, Mission, Skill, Altitude, Forecasts, and Equipment.", "IMSAFE evaluates Inspection, Maneuvering, Security, Authorization, Frequency, and Endurance."], "explanation": "It is a personal-fitness screen, not a substitute for honestly deciding whether you can operate safely.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "IMSAFE checklist", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 80, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What are the three steps in the 3P risk-management model?", "answer": "Perceive hazards, Process their impact, and Perform risk controls.", "distractors": ["The three steps are Plan the route, Pilot the aircraft, and Park safely.", "The three steps are Predict the outcome, Prevent all change, and Proceed immediately.", "The three steps are Identify the mission, Assess the weather, and Mitigate only after launch."], "explanation": "The loop repeats as conditions change throughout the mission.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "3P model", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 81, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which antidote counters the hazardous attitude “The rules do not apply to me”?", "answer": "“Follow the rules. They are usually right.”", "distractors": ["The antidote is, 'Not so fast. Think first.'", "The antidote is, 'It could happen to me.'", "The antidote is, 'Taking chances is foolish.'"], "explanation": "The underlying hazardous attitude is anti-authority.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — Hazardous attitudes", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 82, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which antidote counters impulsivity?", "answer": "“Not so fast. Think first.”", "distractors": ["The antidote is, 'Follow the rules. They are usually right.'", "The antidote is, 'It could happen to me.'", "The antidote is, 'Taking chances is foolish.'"], "explanation": "A deliberate pause breaks the urge to act immediately without comparing safer options.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — Hazardous attitudes", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 83, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which antidote counters invulnerability?", "answer": "“It could happen to me.”", "distractors": ["The antidote is, 'Not so fast. Think first.'", "The antidote is, 'Follow the rules. They are usually right.'", "The antidote is, 'Taking chances is foolish.'"], "explanation": "Recognizing personal exposure makes risk controls feel relevant rather than optional.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — Hazardous attitudes", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 84, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which antidote counters the macho attitude?", "answer": "“Taking chances is foolish.”", "distractors": ["The antidote is, 'It could happen to me.'", "The antidote is, 'Not so fast. Think first.'", "The antidote is, 'I am not helpless. I can make a difference.'"], "explanation": "Skill is demonstrated by disciplined judgment, not by accepting needless risk.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — Hazardous attitudes", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 85, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which antidote counters resignation?", "answer": "“I am not helpless. I can make a difference.”", "distractors": ["“Not so fast. Think first.”", "“It could happen to me.”", "“Follow the rules. They are usually right.”"], "explanation": "The antidote redirects attention toward available actions, resources, and safer outcomes.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — Hazardous attitudes", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 86, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "A client pressures you to launch before a storm arrives because “it will only take five minutes.” Which risk factor is most obvious?", "answer": "External pressure.", "distractors": ["The most obvious factor is aircraft risk caused by deferred maintenance.", "The most obvious factor is pilot risk caused by illness or medication.", "The most obvious factor is invulnerability because the pilot believes accidents happen only to others."], "explanation": "A firm personal minimum and a preplanned cancellation trigger help prevent schedule or customer pressure from driving unsafe choices.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "PAVE — External pressures", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 87, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What alcohol limits apply to a remote PIC, control manipulator, or visual observer?", "answer": "No duty within 8 hours after drinking, while under the influence, with a blood alcohol level of 0.04% or greater, or while using an impairing drug.", "distractors": ["No duty within 12 hours after drinking, with any detectable alcohol, or while taking any prescription medication.", "No duty within 8 hours after drinking; after 8 hours, the person may serve regardless of continuing impairment or alcohol concentration.", "No duty within 24 hours after drinking or with a blood alcohol level of 0.02% or greater, but nonprescription drugs are unrestricted."], "explanation": "Legal minimums do not guarantee fitness; impairment can persist after the numeric limits are met.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.27 incorporating § 91.17", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 88, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What is the core purpose of crew resource management in a small UAS operation?", "answer": "Use people, information, and equipment effectively to manage risk and maintain shared situational awareness.", "distractors": ["Crew resource management centralizes every operational decision with the remote PIC and discourages crewmembers from challenging that decision.", "Crew resource management maximizes mission speed by reducing briefings and delegating risk decisions to automation.", "Crew resource management replaces standard procedures with informal communication whenever an experienced crew is working together."], "explanation": "Clear roles, challenge-and-response communication, and permission to call “stop” help catch errors early.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area V — Crew resource management", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 89, "category": "Operations & Safety", "difficulty": "Foundation", "question": "What is the remote PIC required to determine before every flight about the aircraft?", "answer": "That the small UAS is in a condition for safe operation.", "distractors": ["The remote PIC must determine that the aircraft is still covered by its manufacturer’s warranty.", "The remote PIC must determine only that the battery is fully charged and the registration is current.", "The remote PIC must determine that the aircraft has passed an annual FAA airworthiness inspection."], "explanation": "The check should cover the complete system and mission configuration, not merely whether the aircraft powers on.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.15(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 90, "category": "Operations & Safety", "difficulty": "Applied", "question": "What must be verified about control links during the preflight assessment?", "answer": "That all links between the ground control station and aircraft are working properly.", "distractors": ["Only the satellite-navigation link must be verified because it automatically confirms every other control link.", "Only the Remote ID broadcast must be verified because it serves as the command-and-control link.", "The anti-collision lighting and camera downlink must be verified, but the primary control link may be checked after takeoff."], "explanation": "The remote PIC should also understand lost-link behavior and site-specific interference risks.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 91, "category": "Operations & Safety", "difficulty": "Applied", "question": "How much battery is “enough” for a planned Part 107 flight?", "answer": "Enough for the intended operation plus a prudent reserve for foreseeable contingencies.", "distractors": ["The advertised maximum flight time is enough, even if the plan leaves no reserve for wind or delay.", "Enough energy to reach the farthest mission point is sufficient because the return flight may use the low-battery mode.", "Exactly a 10% reserve is always enough, regardless of weather, battery condition, or landing alternatives."], "explanation": "The rule requires sufficient available power; good risk management adds margin for wind, delay, rerouting, and battery variation.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(d)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 92, "category": "Operations & Safety", "difficulty": "Scenario", "question": "Midflight vibration suggests the aircraft may no longer be safe. What must the remote PIC do?", "answer": "Discontinue the flight and land safely as soon as practical.", "distractors": ["Continue at reduced speed until the planned mission is complete, then inspect the aircraft after landing.", "Hold the aircraft in a hover until the source of the vibration can be diagnosed from the control station.", "Command an immediate high-speed return-to-home so the aircraft spends less time in the unsafe condition."], "explanation": "A person may not continue when they know or have reason to know the small UAS is no longer in a safe condition.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.15(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 93, "category": "Operations & Safety", "difficulty": "Scenario", "question": "Before launch, what should the crew know about a loss of command-and-control link?", "answer": "How the aircraft will respond, where it may travel, and when the crew will trigger the safest contingency action.", "distractors": ["The crew needs no additional plan if the manufacturer has enabled return-to-home by default.", "The crew only needs to know the battery percentage at which the link was lost.", "The crew should expect ATC to track and recover the aircraft after the control link is lost."], "explanation": "Return-to-home settings, altitude, obstacles, geofencing, and recovery areas must be evaluated for the actual site.", "source": {"label": "FAA AC 107-2A", "reference": "Contingency planning and lost link", "url": "https://www.faa.gov/regulations_policies/advisory_circulars/index.cfm/go/document.information/documentID/1038977"}},
  {"id": 94, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A drone begins an uncommanded flyaway toward occupied space. What is the remote PIC’s priority?", "answer": "Protect people and other aircraft, execute the planned emergency response, and notify appropriate authorities when needed.", "distractors": ["The first priority is preserving the aircraft by chasing it and attempting to catch it before it reaches occupied space.", "The first priority is restoring the video feed and recording evidence before taking any other action.", "The first priority is completing the current image capture before warning people in the aircraft’s path."], "explanation": "Do not fixate on saving the aircraft at the expense of airspace awareness or public safety.", "source": {"label": "FAA AC 107-2A", "reference": "Emergency procedures", "url": "https://www.faa.gov/regulations_policies/advisory_circulars/index.cfm/go/document.information/documentID/1038977"}},
  {"id": 95, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A low-flying manned aircraft suddenly enters the operating area. What action takes priority?", "answer": "Yield immediately and maneuver or land the drone to remain well clear.", "distractors": ["Hold the drone’s present position and allow the manned aircraft to maneuver around it.", "Climb the drone above the manned aircraft so their flight paths no longer intersect.", "Continue the mission because a drone operating below 400 feet AGL has priority in that airspace."], "explanation": "The small UAS always bears the duty to yield; mission completion is secondary.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.37", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 96, "category": "Operations & Safety", "difficulty": "Applied", "question": "If a visual observer is used, what communication standard applies?", "answer": "The remote PIC, control manipulator, and visual observer must maintain effective communication at all times.", "distractors": ["The crew only needs to confirm communication before launch; continuous communication is not required after takeoff.", "The crew must use aviation radio continuously, even when another effective communication method is available.", "The visual observer may operate independently without communicating as long as the observer can still see the drone."], "explanation": "They must coordinate scanning and maintain awareness of the aircraft’s position.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.33", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 97, "category": "Operations & Safety", "difficulty": "Scenario", "question": "When may a Part 107 pilot operate a drone from a moving land or water vehicle without a waiver?", "answer": "Only over a sparsely populated area and not while transporting another person’s property for compensation or hire.", "distractors": ["The pilot may operate from any moving vehicle below 400 feet AGL if the driver is not also manipulating the controls.", "The pilot may operate from a moving land or water vehicle over a densely populated area when everyone inside the vehicle consents.", "The exception applies only to moving watercraft; operation from a moving land vehicle always requires a waiver."], "explanation": "Operation from a moving aircraft is prohibited under the standard rule.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.25", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 98, "category": "Operations & Safety", "difficulty": "Applied", "question": "What makes a small UAS eligible for Category 1 operations over people?", "answer": "It weighs 0.55 pounds or less throughout the operation, including attachments, and has no exposed rotating parts that would lacerate human skin.", "distractors": ["It weighs less than 55 pounds and uses propeller guards, regardless of the injury those rotating parts could cause.", "It weighs 0.55 pounds or less only at takeoff and carries an FAA declaration of compliance for Category 2.", "It weighs 3 pounds or less, broadcasts Remote ID, and is flown no faster than 10 knots over people."], "explanation": "Sustained flight over an open-air assembly also requires applicable Remote ID compliance.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.110", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 99, "category": "Operations & Safety", "difficulty": "Applied", "question": "What major restriction distinguishes Category 3 operations over people?", "answer": "They may not be conducted over open-air assemblies and are limited to specified controlled-site or non-sustained-flight conditions.", "distractors": ["Category 3 permits sustained flight over open-air assemblies whenever the drone broadcasts Remote ID.", "Category 3 permits unrestricted sustained flight over moving vehicles but prohibits flight over stationary people.", "Category 3 is limited to drones weighing 0.55 pounds or less and therefore has no site-access restrictions."], "explanation": "At a closed or restricted-access site, people must be on notice; otherwise sustained flight is limited to participants or protected people.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.125", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 100, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A Category 2 drone must cross a public road with moving traffic. What standard Part 107 limitation applies?", "answer": "It must not maintain sustained flight over moving vehicles unless the operation is within or over a closed/restricted-access site where vehicle occupants are on notice.", "distractors": ["Sustained flight over moving vehicles is permitted whenever the drone remains below 400 feet AGL.", "Sustained flight over moving vehicles is permitted for every drone weighing 0.55 pounds or less.", "Flight over moving vehicles is prohibited even inside a closed or restricted-access site where occupants have been notified."], "explanation": "The aircraft must also meet its Category 2 operating requirements; a brief transit is not permission to loiter over traffic.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.145", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 101, "category": "Regulations", "difficulty": "Foundation", "question": "Under Part 107, what is a control station?", "answer": "The interface a remote pilot uses to control the flight path of the small unmanned aircraft.", "distractors": ["A control station is the physical takeoff and landing area reserved for the small unmanned aircraft.", "A control station is the Remote ID module that broadcasts the aircraft’s identification and location.", "A control station is any location from which the remote PIC can maintain unaided visual line of sight."], "explanation": "A control station is defined by its function; it can be a handheld controller, computer interface, or another system used to direct the aircraft.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.3 — Control station", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 102, "category": "Regulations", "difficulty": "Foundation", "question": "What does the term “small unmanned aircraft system” include beyond the aircraft itself?", "answer": "The associated elements required for safe and efficient operation, including communication links and control components.", "distractors": ["The system includes only the aircraft and any payload physically attached to it.", "The system includes the aircraft, remote PIC, control manipulator, and visual observer as system components.", "The system includes the aircraft, its airspace authorization, and the operator’s liability insurance."], "explanation": "Part 107 distinguishes the aircraft from the complete system used to operate it in the National Airspace System.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.3 — Small unmanned aircraft system", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 103, "category": "Regulations", "difficulty": "Applied", "question": "What documents must a remote PIC physically possess and keep readily accessible while exercising certificate privileges?", "answer": "A Remote Pilot Certificate with a small UAS rating and identification.", "distractors": ["The remote PIC must carry the Remote Pilot Certificate, but separate identification is optional.", "The remote PIC must carry the aircraft registration and government identification, but not the pilot certificate.", "The remote PIC must carry a medical certificate and flight logbook whenever exercising Part 107 privileges."], "explanation": "Having a certificate number saved elsewhere is not enough; the certificate and acceptable identification must be physically possessed and readily accessible.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.7(a)(1)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 104, "category": "Regulations", "difficulty": "Foundation", "question": "Who may request to inspect a remote pilot’s certificate and identification under § 107.7?", "answer": "The FAA Administrator, an authorized NTSB or TSA representative, or any federal, state, or local law-enforcement officer.", "distractors": ["Only the FAA Administrator may request the certificate and identification.", "Any airport manager or property owner may demand the certificate and identification under § 107.7.", "Only the remote pilot’s employer or client may request the certificate and identification."], "explanation": "The regulation expressly identifies these officials; a certificated remote pilot must present the documents when one of them requests inspection.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.7(a)(2)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 105, "category": "Regulations", "difficulty": "Scenario", "question": "The FAA Administrator requests a compliance inspection during an inquiry. What must the Part 107 participants allow?", "answer": "They must allow the Administrator to test or inspect the small UAS, the remote PIC, the person manipulating the flight controls, and—if used—the visual observer.", "distractors": ["Participants need allow inspection of the aircraft only after the FAA obtains a search warrant.", "Participants need provide maintenance records, but the FAA may not inspect the aircraft or applicable crewmembers.", "Participants may postpone every requested test or inspection for 30 calendar days without FAA approval."], "explanation": "The remote PIC, visual observer, owner, operator, or control manipulator may have to allow access, but the owner and operator are not listed as inspection subjects.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.7(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 106, "category": "Regulations", "difficulty": "Scenario", "question": "A visual observer knows a medication is slowing their reactions. May that person participate in the operation?", "answer": "No, not if the condition could interfere with safe operation.", "distractors": ["Yes, because the medication rule applies to the remote PIC but not to a visual observer.", "Yes, if the visual observer is supervised by a remote PIC who has not taken the medication.", "Yes, because a prescribed or over-the-counter medication is permitted regardless of its effect on reaction time."], "explanation": "The medical-condition rule applies to the remote PIC, control manipulator, visual observer, and any direct participant—not only to the person holding the controller.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.17", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 107, "category": "Regulations", "difficulty": "Applied", "question": "What must the remote PIC ensure would be true if control of the drone were lost for any reason?", "answer": "The drone would pose no undue hazard to other people, other aircraft, or other property.", "distractors": ["The remote PIC need only ensure that the drone would remain below 400 feet AGL after control is lost.", "The remote PIC need only confirm that an automatic return-to-home function is enabled.", "The remote PIC must ensure that the aircraft could be recovered without damage, even if it creates a hazard to others."], "explanation": "Site selection, containment areas, lost-link settings, and safe routing should all support this required outcome.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.19(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 108, "category": "Regulations", "difficulty": "Foundation", "question": "What kind of operation does Part 107 prohibit as careless or reckless?", "answer": "An operation conducted in a manner that endangers another person’s life or property.", "distractors": ["A careless or reckless operation is any flight that causes damage to the small unmanned aircraft itself.", "A careless or reckless operation is any flight conducted without liability insurance, even when no one is endangered.", "A careless or reckless operation is any flight that briefly loses GPS reception but remains under control."], "explanation": "Meeting numerical limits does not excuse conduct that creates an unreasonable danger.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.23(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 109, "category": "Regulations", "difficulty": "Scenario", "question": "May a remote pilot control a Part 107 drone while riding in a moving aircraft?", "answer": "No. Part 107 prohibits operating a small UAS from a moving aircraft.", "distractors": ["Yes, when the moving aircraft is over a sparsely populated area and the drone carries no property for compensation.", "Yes, when the remote pilot remains below 400 feet AGL and maintains visual line of sight.", "Yes, when another certificated remote pilot is aboard the moving aircraft and can take control."], "explanation": "Part 107 prohibits operating a small UAS from a moving aircraft; the limited exception applies only to certain operations from moving land or water-borne vehicles.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.25(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 110, "category": "Regulations", "difficulty": "Foundation", "question": "May a small UAS carry hazardous material during a standard Part 107 operation?", "answer": "No. A small unmanned aircraft may not carry hazardous material.", "distractors": ["Yes, if the entire drone and hazardous payload weigh 0.55 pounds or less.", "Yes, if the material is packaged and secured according to the manufacturer’s instructions.", "Yes, whenever the remote PIC documents the material during the preflight assessment."], "explanation": "Section 107.36 prohibits a small unmanned aircraft from carrying material defined as hazardous under 49 CFR 171.8.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.36", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 111, "category": "Regulations", "difficulty": "Applied", "question": "Outside Alaska, which periods count as civil twilight for the Part 107 lighting rule?", "answer": "The 30 minutes before official sunrise and the 30 minutes after official sunset.", "distractors": ["Civil twilight is the 60 minutes before official sunrise and the 60 minutes after official sunset.", "Civil twilight is the 30 minutes after official sunrise and the 30 minutes before official sunset.", "Civil twilight is the entire period from official sunrise through official sunset."], "explanation": "Alaska uses the civil-twilight period defined in the Air Almanac rather than the standard 30-minute rule.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.29(b)–(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 112, "category": "Regulations", "difficulty": "Applied", "question": "What must seeing the drone throughout the flight allow the crew to determine under the VLOS rule?", "answer": "Its location, attitude, altitude, and direction; surrounding air traffic or hazards; and whether it endangers another person or property.", "distractors": ["Seeing the drone must allow the crew to determine only its GPS coordinates, battery state, and Remote ID status.", "Seeing the drone must allow the crew to determine only its color and orientation relative to the control station.", "Seeing the drone must allow the crew to calculate its exact groundspeed and distance using unaided vision."], "explanation": "Merely seeing a distant dot is insufficient if the crew cannot make the determinations required by § 107.31.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.31(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 113, "category": "Regulations", "difficulty": "Applied", "question": "When a visual observer is used, what two observation tasks must the crew coordinate?", "answer": "Scanning the operating airspace for collision hazards and maintaining awareness of the drone’s position through direct visual observation.", "distractors": ["The crew must coordinate monitoring local weather and recording battery cycles.", "The crew must coordinate checking Remote ID broadcasts and reading GPS coordinates.", "The crew must coordinate radio calls with ATC and communications with the client."], "explanation": "The remote PIC, control manipulator, and visual observer share these coordinated see-and-avoid duties.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.33(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 114, "category": "Regulations", "difficulty": "Foundation", "question": "Which four subjects must the remote PIC include in the required preflight assessment of the operating environment?", "answer": "Local weather, local airspace and flight restrictions, the location of people and property on the surface, and other ground hazards.", "distractors": ["The assessment must cover battery charge, propeller condition, software version, and camera settings.", "The assessment must cover aircraft registration, liability insurance, client permission, and local privacy rules.", "The assessment must cover pilot fitness, payload value, mission revenue, and postflight data storage."], "explanation": "The assessment must consider risks both on the surface and in the air in the immediate vicinity.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 115, "category": "Regulations", "difficulty": "Applied", "question": "What information must the remote PIC give everyone directly participating in the operation before flight?", "answer": "The operating conditions, emergency and contingency procedures, roles and responsibilities, and potential hazards.", "distractors": ["The remote PIC must brief only the planned route and maximum altitude before flight.", "The remote PIC must give participants copies of the pilot certificate, aircraft registration, and airspace authorization.", "The remote PIC must brief the client’s desired images, project deadline, payment terms, and delivery method."], "explanation": "A complete crew briefing creates shared expectations before anyone performs an operational role.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 116, "category": "Regulations", "difficulty": "Scenario", "question": "A current flight restriction conflicts with a planned Part 107 mission. May the remote PIC ignore it because the drone will remain below 400 feet?", "answer": "No. The remote PIC must comply with the applicable flight restriction.", "distractors": ["Yes, because flight restrictions apply to manned aircraft but not to drones below 400 feet AGL.", "Yes, if the remote PIC remains in Class G airspace and maintains visual line of sight.", "Yes, if the mission lasts less than 30 minutes and no manned aircraft are visible."], "explanation": "Section 107.47 requires the remote PIC to comply with the applicable flight restrictions in §§ 91.137 through 91.145 and § 99.7.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.47", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 117, "category": "Regulations", "difficulty": "Foundation", "question": "May a Part 107 small UAS operate with an ATC transponder switched on?", "answer": "Only if the FAA Administrator has authorized it; otherwise the transponder must not be on.", "distractors": ["The transponder must be switched on whenever the drone enters controlled airspace.", "The transponder may be switched on whenever it was installed by the aircraft manufacturer.", "The transponder is required for every Part 107 flight above 200 feet AGL."], "explanation": "Part 107 separately restricts transponder transmission to prevent unnecessary surveillance-system effects.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.52", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 118, "category": "Regulations", "difficulty": "Foundation", "question": "May a Part 107 small UAS transmit ADS-B Out during flight?", "answer": "Only if the FAA Administrator has authorized it; otherwise ADS-B Out may not be in transmit mode.", "distractors": ["ADS-B Out must transmit during every operation in Class B, C, or D airspace.", "ADS-B Out may transmit during any flight because additional electronic visibility is always permitted.", "ADS-B Out may transmit without authorization when the small UAS remains below 400 feet AGL."], "explanation": "Receiving traffic information is different from transmitting ADS-B Out; § 107.53 addresses the transmit function.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.53", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 119, "category": "Regulations", "difficulty": "Foundation", "question": "For how long may the FAA issue a temporary Remote Pilot Certificate with a small UAS rating?", "answer": "Up to 120 calendar days.", "distractors": ["The temporary certificate may remain valid for up to 60 calendar days.", "The temporary certificate may remain valid for up to 90 calendar days.", "The temporary certificate may remain valid for 24 calendar months."], "explanation": "It can expire sooner on its printed expiration date, when the permanent certificate arrives, or when the applicant receives a denial or revocation notice.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.64", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 120, "category": "Regulations", "difficulty": "Foundation", "question": "How long must an applicant wait to retake an FAA knowledge test after failing it?", "answer": "14 calendar days.", "distractors": ["The applicant must wait 7 calendar days before retaking the knowledge test.", "The applicant must wait 14 business days before retaking the knowledge test.", "The applicant must wait 30 calendar days before retaking the knowledge test."], "explanation": "The waiting period begins after the failed test and applies before the applicant may reapply.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.71", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 121, "category": "Regulations", "difficulty": "Applied", "question": "What is the application-and-testing consequence if the FAA finds that an applicant cheated on a knowledge test?", "answer": "For one year after the violation, the applicant may not apply for any certificate, rating, or authorization issued under 14 CFR Chapter I and may not apply for or take any test under that chapter.", "distractors": ["The applicant may not retake that knowledge test for 90 days, but may apply for other certificates immediately.", "The applicant may not apply for a certificate or take an FAA test for six calendar months.", "The applicant is permanently barred from every FAA certificate and knowledge test."], "explanation": "A certificate or rating the person already holds may also be suspended or revoked.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.69", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 122, "category": "Regulations", "difficulty": "Scenario", "question": "A remote pilot changed permanent mailing addresses 31 days ago but has not notified the FAA. May the pilot exercise certificate privileges?", "answer": "No, not until the FAA is notified of the address change.", "distractors": ["Yes, because certificate privileges continue for 60 days after a permanent address change.", "Yes, because the pilot may wait until the next certificate renewal to report the new address.", "Yes, because only a change of email address must be reported to the FAA within 30 days."], "explanation": "Section 107.77 gives a certificate holder 30 days after a permanent mailing-address change before privileges become unavailable.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.77(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 123, "category": "Regulations", "difficulty": "Applied", "question": "What injury-severity limit must a drone meet to be eligible for Category 2 operations over people?", "answer": "It must not cause injury equivalent to or greater than an 11-foot-pound rigid-object impact.", "distractors": ["The drone must not cause injury equivalent to or greater than a 25-foot-pound rigid-object impact.", "The drone must weigh 0.55 pounds or less throughout the operation, regardless of impact severity.", "The drone must not cause injury equivalent to or greater than an 11-joule rigid-object impact."], "explanation": "The design must also have no exposed rotating parts that would lacerate skin and no safety defects, and the aircraft must satisfy the applicable declaration and labeling rules.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.120(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 124, "category": "Regulations", "difficulty": "Applied", "question": "What injury-severity limit must a drone meet to be eligible for Category 3 operations over people?", "answer": "It must not cause injury equivalent to or greater than a 25-foot-pound rigid-object impact.", "distractors": ["The drone must not cause injury equivalent to or greater than an 11-foot-pound rigid-object impact.", "The drone must not cause injury equivalent to or greater than a 55-foot-pound rigid-object impact.", "The drone must not cause injury equivalent to or greater than a 25-joule rigid-object impact."], "explanation": "Category 3 also requires no exposed skin-lacerating rotating parts, no safety defects, and compliance with its declaration, labeling, and operating restrictions.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.130(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 125, "category": "Regulations", "difficulty": "Applied", "question": "What aircraft-level requirements distinguish a Category 4 operation over people?", "answer": "The drone must have a Part 21 airworthiness certificate, be operated within approved limitations that permit flight over people, and meet the prescribed maintenance and inspection requirements.", "distractors": ["The drone must weigh 0.55 pounds or less and have no exposed rotating parts capable of lacerating skin.", "The drone must meet the 11-foot-pound injury limit and have an FAA-accepted declaration of compliance, but needs no airworthiness certificate.", "The drone must meet the 25-foot-pound injury limit and remain over a closed site, but needs no approved operating limitations or maintenance program."], "explanation": "Category 4 relies on airworthiness certification and continued-airworthiness controls rather than the Category 1 weight limit or Category 2 and 3 injury thresholds.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.140", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 126, "category": "Airspace & Charts", "difficulty": "Scenario", "question": "A UAS Facility Map shows “200” over the planned site. Does that number itself authorize flight up to 200 feet AGL?", "answer": "No; the pilot must still obtain a Part 107 airspace authorization.", "distractors": ["Yes; the grid number is an automatic authorization up to 200 feet AGL during daylight.", "Yes; the pilot may fly up to 200 feet after notifying the nearest airport operator.", "Yes; a Standard Remote ID drone may use the published grid altitude without a separate authorization."], "explanation": "The grid value is the maximum altitude the FAA may authorize without additional safety analysis, not permission to fly.", "source": {"label": "FAA UAS Facility Maps", "reference": "Maximum altitudes and authorization notice", "url": "https://www.faa.gov/uas/commercial_operators/uas_facility_maps"}},
  {"id": 127, "category": "Airspace & Charts", "difficulty": "Applied", "question": "How can a Part 107 pilot request an altitude above a UAS Facility Map value, including inside a zero-foot grid?", "answer": "Submit a LAANC further-coordination request for an altitude at or below 400 feet AGL at least 72 hours before the requested start time.", "distractors": ["Submit a standard LAANC request at the published grid altitude and climb above it after receiving the automatic approval.", "Submit a FAADroneZone waiver request up to 90 days in advance for any altitude below 1,200 feet AGL.", "Call the control tower immediately before launch and request a verbal altitude increase above the grid value."], "explanation": "An Air Traffic Manager reviews the request; submitting it does not guarantee approval.", "source": {"label": "FAA Part 107 Airspace Authorizations", "reference": "LAANC further coordination", "url": "https://www.faa.gov/uas/commercial_operators/part_107_airspace_authorizations"}},
  {"id": 128, "category": "Airspace & Charts", "difficulty": "Applied", "question": "Which FAA system handles Part 107 authorization requests for airports that are not LAANC-enabled?", "answer": "FAADroneZone.", "distractors": ["The pilot must telephone the LAANC service desk to obtain an authorization for a nonparticipating airport.", "The pilot must submit the authorization request through IACRA.", "The pilot must submit the authorization request through the B4UFLY service."], "explanation": "Those requests are processed manually rather than through LAANC’s near-real-time approval path.", "source": {"label": "FAA Part 107 Airspace Authorizations", "reference": "FAADroneZone authorizations", "url": "https://www.faa.gov/uas/commercial_operators/part_107_airspace_authorizations"}},
  {"id": 129, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What are the general vertical limits of Class A airspace, and is it specifically charted on sectionals?", "answer": "It generally extends from 18,000 feet MSL through Flight Level 600 and is not specifically charted.", "distractors": ["Class A generally extends from 10,000 feet MSL through Flight Level 180 and is outlined by solid blue lines.", "Class A generally extends from 14,500 feet MSL through Flight Level 600 and is shown by shaded blue boundaries.", "Class A generally extends from the surface to but not including 18,000 feet MSL and is shown by dashed blue lines."], "explanation": "Class A is far above normal Part 107 altitudes, but its limits remain part of the FAA airspace-knowledge framework.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-2 — Class A Airspace", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 130, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What are the usual dimensions of Class C airspace?", "answer": "A 5-NM-radius core from the surface to 4,000 feet above airport elevation and a 10-NM-radius shelf from no lower than 1,200 feet to 4,000 feet above airport elevation.", "distractors": ["Class C normally has a 4-NM-radius surface area extending to 2,500 feet above airport elevation with no outer shelf.", "Class C normally has a 10-NM-radius core from the surface to 10,000 feet MSL and a 20-NM-radius shelf beginning at 1,200 feet AGL.", "Class C normally has a 5-NM-radius core from 700 feet AGL to 4,000 feet MSL and a shelf extending to 30 NM."], "explanation": "Every Class C area is individually tailored, so the current charted boundaries and altitudes control.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-4 — Class C Airspace", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 131, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "How high does Class D airspace generally extend above its primary airport?", "answer": "From the surface to 2,500 feet above airport elevation, with the top charted in MSL.", "distractors": ["Class D generally extends from the surface to 400 feet AGL, with the top charted in AGL.", "Class D generally extends from the surface to 4,000 feet above airport elevation, with the top charted in AGL.", "Class D generally begins at 1,200 feet AGL and extends to but not including 18,000 feet MSL."], "explanation": "Class D dimensions are individually tailored, so the sectional and Chart Supplement must be used for the actual location.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-5 — Class D Airspace", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 132, "category": "Airspace & Charts", "difficulty": "Scenario", "question": "What can happen to part-time Class D surface airspace when its control tower closes?", "answer": "It can revert to a Class E surface area or to Class G airspace, as published for that airport.", "distractors": ["The airspace remains Class D continuously even when the tower is closed.", "The airspace automatically becomes Class G whenever the tower closes, regardless of published information.", "The airspace automatically converts to Class C until the tower reopens."], "explanation": "Check the Chart Supplement’s airspace entry and current NOTAMs rather than assuming the dashed-blue area remains Class D around the clock.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-5 — Part-time Class D status", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 133, "category": "Airspace & Charts", "difficulty": "Applied", "question": "Do Class E transition areas beginning at 700 or 1,200 feet AGL turn off when a nearby airport tower closes?", "answer": "No; those transition areas remain in effect continuously.", "distractors": ["Yes; every 700- or 1,200-foot Class E transition area turns off when the associated tower closes.", "Yes; the transition area automatically becomes Class G from the surface to 18,000 feet MSL.", "Yes; the transition area becomes a Class E surface area only during daylight hours."], "explanation": "Airport surface-area status can change with tower hours, but the charted 700-foot and 1,200-foot transition areas do not.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-6 — Class E transition areas", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 134, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What class of airspace normally forms a federal airway, and what are its usual vertical limits?", "answer": "Class E airspace, normally from 1,200 feet AGL up to but not including 18,000 feet MSL.", "distractors": ["A federal airway is normally Class D airspace from the surface to 2,500 feet above airport elevation.", "A federal airway is normally Class G airspace from the surface to 700 feet AGL.", "A federal airway is normally Class A airspace from 18,000 feet MSL through Flight Level 600."], "explanation": "A specifically designated segment may use a different floor, so the applicable chart remains controlling.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-6 — Federal airways and low-altitude RNAV routes", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 135, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "Which prefixes identify VOR federal airways and low-altitude RNAV routes?", "answer": "“V” identifies VOR federal airways; “T” identifies low-altitude RNAV T-routes; and “TK” identifies helicopter RNAV routes.", "distractors": ["“J” identifies VOR federal airways, while “Q” identifies low-altitude RNAV routes.", "“L” identifies VOR federal airways, while “R” identifies low-altitude RNAV routes.", "“A” identifies VOR federal airways, while “B” identifies low-altitude RNAV routes."], "explanation": "The AIM states that low-altitude RNAV routes include both T-routes and TK helicopter RNAV routes.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-6 — Federal airway and RNAV route identifiers", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 136, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "Which two types of special-use airspace are regulatory?", "answer": "Prohibited areas and restricted areas.", "distractors": ["Alert areas and warning areas are the two regulatory types of special-use airspace.", "Military operations areas and controlled firing areas are the two regulatory types of special-use airspace.", "National security areas and alert areas are the two regulatory types of special-use airspace."], "explanation": "Warning areas, military operations areas, alert areas, controlled firing areas, and national security areas are categorized as nonregulatory special-use airspace.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-1 — Special Use Airspace", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 137, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What does a warning area tell a pilot?", "answer": "Potentially hazardous activity exists in defined airspace extending from 3 NM outward from the U.S. coast.", "distractors": ["A warning area identifies prohibited flight over a sensitive land facility inside the United States.", "A warning area identifies a high volume of pilot training within inland domestic airspace.", "A warning area identifies a voluntary-avoidance zone established solely for national security."], "explanation": "A warning area can lie over domestic waters, international waters, or both and warns nonparticipating pilots of the danger.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-4 — Warning Areas", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 138, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What activity should a pilot expect in an alert area, and who is responsible for collision avoidance?", "answer": "A high volume of pilot training or unusual aerial activity; both participating and transiting pilots share collision-avoidance responsibility.", "distractors": ["An alert area contains invisible hazards that require advance permission, and the controlling agency alone provides collision avoidance.", "An alert area is reserved for military exercises, and participating military pilots alone are responsible for collision avoidance.", "An alert area transfers all collision-avoidance responsibility to ATC whenever the area is active."], "explanation": "An alert area is advisory rather than a blanket prohibition, but it signals a need for heightened traffic awareness.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-6 — Alert Areas", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 139, "category": "Airspace & Charts", "difficulty": "Applied", "question": "Why are controlled firing areas normally not shown on aeronautical charts?", "answer": "Their hazardous activity stops immediately when monitoring indicates a nonparticipating aircraft is approaching.", "distractors": ["Controlled firing areas are omitted because their locations and activities are classified.", "Controlled firing areas are omitted because they may operate only at night when VFR charts are not used.", "Controlled firing areas are omitted because all activity remains below 400 feet AGL and cannot affect aircraft."], "explanation": "Because the activity is suspended, a nonparticipating aircraft should not have to alter its flight path around a controlled firing area.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-7 — Controlled Firing Areas", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 140, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What does a national security area ask pilots to do, and how can that request become mandatory?", "answer": "Pilots are asked to avoid it voluntarily; flight can be temporarily prohibited under § 99.7 and announced by NOTAM.", "distractors": ["A national security area always prohibits flight, and only the military may authorize entry.", "A national security area requires pilots to contact its controlling agency, but the request can never become mandatory.", "A national security area is merely advisory and has no regulatory process that can temporarily prohibit flight."], "explanation": "An NSA protects locations requiring increased security and safety for facilities on the ground.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-8 — National Security Areas", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 141, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "For permanent special-use airspace that is charted—all permanent SUA except controlled firing areas—what operating information appears?", "answer": "Its hours of operation, altitude limits, and controlling agency.", "distractors": ["Charts show the forecast weather, radio frequency, and recommended cruising altitude for each permanent special-use area.", "Charts show only the lateral boundary because activity times and altitude limits are never published.", "Charts show local-time operating hours, airport traffic-pattern altitude, and the nearest flight service station."], "explanation": "These details help a pilot determine when the airspace may be active and whom to contact for status information.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-1 — Permanent SUA charting", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 142, "category": "Airspace & Charts", "difficulty": "Scenario", "question": "A sectional shows no special-use area over the site. Could a temporary MOA or temporary restricted area still be active there?", "answer": "Yes; temporary MOAs and temporary restricted areas are not charted.", "distractors": ["No; every temporary MOA and temporary restricted area must appear on the current sectional before becoming active.", "No; temporary special-use airspace can exist only during a presidential movement covered by a TFR.", "No; an uncharted temporary area does not become effective until the next 56-day chart cycle."], "explanation": "Check current NOTAM and FAA special-use-airspace information for temporary activity that a sectional cannot display.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-1 and 3-4-3 — Temporary SUA", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 143, "category": "Airspace & Charts", "difficulty": "Applied", "question": "How can a pilot obtain the current status of a special-use airspace area?", "answer": "Contact the using or controlling agency and check applicable airspace NOTAMs and FAA SUA information.", "distractors": ["Check only the sectional’s publication date; a current chart confirms whether the area is active.", "Monitor the nearest airport’s CTAF because every active special-use area broadcasts its status there.", "Assume the area is inactive unless an ATC controller contacts the pilot during the flight."], "explanation": "The chart-margin frequency can identify the controlling agency, while current notices reveal activations or temporary changes.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-9 — Obtaining SUA status", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 144, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What is the scale of an FAA Sectional Aeronautical Chart?", "answer": "1:500,000, or about 6.86 nautical miles per inch.", "distractors": ["The scale is 1:250,000, or about 3.43 nautical miles per inch.", "The scale is 1:1,000,000, or about 13.7 nautical miles per inch.", "The scale is 1:100,000, or about 1.37 nautical miles per inch."], "explanation": "Sectionals provide the primary VFR planning view of airports, controlled and special-use airspace, obstructions, navigation aids, and terrain.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM Chapter 9 — Sectional Aeronautical Charts", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap9_section_1.html"}},
  {"id": 145, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What is the scale of a VFR Terminal Area Chart, and why is it useful?", "answer": "1:250,000; its larger scale provides more detail around complex Class B and Class C terminal areas.", "distractors": ["The scale is 1:500,000, and it is useful because it covers twice as much area with more airport detail than a sectional.", "The scale is 1:1,000,000, and it is useful for detailed surface navigation inside Class D airspace.", "The scale is 1:250,000, but it provides less detail than a sectional because it depicts only terminal frequencies."], "explanation": "At about 3.43 nautical miles per inch, a TAC shows terminal-area detail more clearly than a sectional.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM Chapter 9 — VFR Terminal Area Charts", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap9_section_1.html"}},
  {"id": 146, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What do blue and magenta airport symbols generally distinguish on a VFR chart?", "answer": "Blue identifies an airport with a control tower; magenta identifies an airport without one.", "distractors": ["Blue identifies an airport without a control tower, while magenta identifies an airport with a control tower.", "Blue identifies a paved airport, while magenta identifies an unpaved airport, regardless of tower status.", "Blue identifies a public-use airport, while magenta identifies a private-use airport, regardless of tower status."], "explanation": "The color does not prove a part-time tower is open at that moment; check its published hours. Airport names and related data normally match the symbol color.", "source": {"label": "FAA Aeronautical Chart Users' Guide", "reference": "VFR chart legend — Airport symbols", "url": "https://www.faa.gov/air_traffic/flight_info/aeronav/digital_products/aero_guide/"}},
  {"id": 147, "category": "Airspace & Charts", "difficulty": "Applied", "question": "Where should a pilot look for airport details that cannot be shown clearly on a sectional, such as operating hours, runway widths, and lighting codes?", "answer": "The applicable FAA Chart Supplement.", "distractors": ["The pilot should use the Remote Pilot Airman Certification Standards for airport operating hours and runway dimensions.", "The pilot should use the airport’s current Terminal Aerodrome Forecast for runway widths and lighting codes.", "The pilot should use the UAS Facility Map for runway dimensions, lighting, and airport operating hours."], "explanation": "The Chart Supplement expands the chart with airport, communications, weather-source, procedure, and facility details that are impractical to depict graphically.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM Chapter 9 — Chart Supplement", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap9_section_1.html"}},
  {"id": 148, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "Unless a VFR chart states otherwise, what reference is used for its altitudes and times?", "answer": "Altitudes are in feet MSL and times are Coordinated Universal Time (UTC).", "distractors": ["Altitudes are in feet AGL and times are local standard time.", "Altitudes are in feet MSL and times are local standard time.", "Altitudes are in feet AGL and times are Coordinated Universal Time."], "explanation": "AGL values and local-time entries are specifically identified when used; the default convention is MSL and UTC.", "source": {"label": "FAA Aeronautical Chart Users' Guide", "reference": "Chart Users' Guide — Introduction and conventions", "url": "https://www.faa.gov/air_traffic/flight_info/aeronav/digital_products/aero_guide/"}},
  {"id": 149, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "How often are FAA Sectional Aeronautical Charts and VFR Terminal Area Charts normally revised?", "answer": "Every 56 days.", "distractors": ["They are normally revised every 28 days.", "They are normally revised every 90 days.", "They are normally revised once each calendar year."], "explanation": "A pilot should confirm the effective date because aeronautical information can change from one edition to the next.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM Chapter 9 — VFR chart revision cycle", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap9_section_1.html"}},
  {"id": 150, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "How far in advance may a pilot submit a LAANC airspace-authorization request?", "answer": "Up to 90 days before the planned flight.", "distractors": ["A LAANC request may be submitted up to 30 days before the planned flight.", "A LAANC request may be submitted up to 120 days before the planned flight.", "A LAANC request may be submitted up to 365 days before the planned flight."], "explanation": "At-or-below-grid requests may be made on the flight date, while above-grid further-coordination requests need at least 72 hours for review.", "source": {"label": "FAA Part 107 Airspace Authorizations", "reference": "LAANC request timing", "url": "https://www.faa.gov/uas/commercial_operators/part_107_airspace_authorizations"}},
  {"id": 151, "category": "Weather", "difficulty": "Applied", "question": "How should a pilot decode the METAR remark “PK WND 28035/15”?", "answer": "The peak wind was from 280° true at 35 knots, occurring 15 minutes after the hour.", "distractors": ["The peak wind was from 280° true at 15 knots, occurring 35 minutes after the hour.", "The peak wind was from 280° magnetic at 35 knots, occurring 15 minutes after the hour.", "The prevailing wind was from 280° true at 35 knots and lasted for 15 minutes."], "explanation": "The peak-wind remark reports direction, maximum speed, and the minute when that peak occurred.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR remarks — peak wind", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 152, "category": "Weather", "difficulty": "Applied", "question": "What visibility does “P6SM” report in a TAF?", "answer": "Prevailing visibility is greater than 6 statute miles.", "distractors": ["Prevailing visibility is exactly 6 statute miles.", "Prevailing visibility is at least 6 statute miles, including exactly 6 miles.", "Prevailing visibility is less than 6 statute miles."], "explanation": "The P prefix means “more than,” and SM identifies statute miles.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "TAF prevailing-visibility group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 153, "category": "Weather", "difficulty": "Applied", "question": "How should a remote pilot read the METAR wind group “VRB04KT”?", "answer": "The wind direction is variable at 4 knots.", "distractors": ["The wind is from 040° true at a variable speed.", "The wind is calm with occasional gusts to 4 knots.", "The wind is from 040° true, and VRB indicates that the visibility is variable."], "explanation": "VRB replaces a specific direction when the wind direction cannot be stated as one representative value.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR wind group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 154, "category": "Weather", "difficulty": "Applied", "question": "What does the weather code “VCSH” tell a pilot?", "answer": "Showers are occurring in the vicinity of the reporting station, not necessarily at the station itself.", "distractors": ["Showers are occurring directly at the reporting station.", "Showers are forecast to begin later in the observation period.", "Rain is evaporating before reaching the ground in the vicinity of the station."], "explanation": "VC is a proximity qualifier, so nearby showers may still affect wind, visibility, and the planned operating area.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR vicinity and precipitation codes", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 155, "category": "Weather", "difficulty": "Applied", "question": "What does “VV003” mean in a METAR sky-condition group?", "answer": "The sky is obscured, with vertical visibility of 300 feet AGL.", "distractors": ["Visibility is varying around 3 statute miles.", "The sky is obscured, with vertical visibility of 3,000 feet.", "A broken cloud layer has a base 300 feet above ground level."], "explanation": "VV is used when an indefinite ceiling prevents normal cloud-layer reporting; the three digits give hundreds of feet AGL.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR vertical-visibility group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 156, "category": "Weather", "difficulty": "Applied", "question": "What does the METAR group “R27/2400FT” report?", "answer": "Runway visual range for Runway 27 is 2,400 feet.", "distractors": ["Runway 27 has 2,400 feet of usable pavement remaining.", "Runway visual range for Runway 27 is 24,000 feet.", "Prevailing visibility on the magnetic course for Runway 27 is 2.4 statute miles."], "explanation": "RVR describes visibility along a specific runway; it is not a substitute for evaluating Part 107 flight visibility from the control station.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR runway-visual-range group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 157, "category": "Weather", "difficulty": "Applied", "question": "In METAR remarks, what does “RAB12” mean?", "answer": "Rain began 12 minutes after the hour.", "distractors": ["Rain ended 12 minutes after the hour.", "Rain began at 1200 UTC.", "The station measured 0.12 inch of rain during the previous hour."], "explanation": "Remark groups may record when significant precipitation began or ended within the observation hour.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR remarks — beginning and ending precipitation", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 158, "category": "Weather", "difficulty": "Foundation", "question": "What does “AO2” identify in the remarks of an automated METAR?", "answer": "An automated station equipped with a precipitation discriminator.", "distractors": ["It identifies an automated station without a precipitation discriminator.", "It identifies a manually observed station that has been augmented by a second observer.", "It identifies an automated station equipped only with a lightning detector."], "explanation": "AO2 is the official code for an automated station with a precipitation discriminator; AO1 identifies one without that equipment.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR automated-station type", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 159, "category": "Weather", "difficulty": "Applied", "question": "What sea-level pressure is encoded by the METAR remark “SLP132”?", "answer": "1,013.2 hectopascals.", "distractors": ["The encoded sea-level pressure is 913.2 hectopascals.", "The encoded sea-level pressure is 1,132.0 hectopascals.", "The encoded sea-level pressure is 1,031.2 hectopascals."], "explanation": "The three-digit SLP value is decoded to the plausible pressure nearest 1,000 hPa and a decimal is inserted before the last digit.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR remarks — sea-level pressure", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 160, "category": "Weather", "difficulty": "Applied", "question": "What probability and time window does “PROB30 0202/0206” describe in a TAF?", "answer": "A 30% probability from 0200 through 0600 UTC on the second day of the month.", "distractors": ["It describes a 30% probability from 0200 UTC on the second day through 0600 UTC on the third day.", "It describes a 30% probability from 0002 through 0006 UTC on the second day.", "It makes the stated conditions prevailing from 0200 through 0600 UTC on the second day."], "explanation": "PROB30 expresses the chance of specified conditions, followed by the UTC day-and-hour period when they may occur.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "TAF probability group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 161, "category": "Weather", "difficulty": "Foundation", "question": "What does “AMD” mean when it appears after the TAF report type?", "answer": "The terminal forecast has been amended after its original issuance.", "distractors": ["It means the terminal forecast has been canceled and will not be replaced.", "It means only a typographical error was corrected without changing the forecast.", "It means the report is an automated METAR rather than a terminal forecast."], "explanation": "An amendment updates the forecast when expected conditions have changed enough to require a revised product.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "TAF report modifiers", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 162, "category": "Weather", "difficulty": "Applied", "question": "Decode the TAF wind-shear group “WS020/24040KT.”", "answer": "Low-level wind shear is forecast at 2,000 feet AGL, with wind there from 240° true at 40 knots.", "distractors": ["Wind shear is forecast at 200 feet MSL, with wind there from 240° true at 40 knots.", "Wind shear is forecast at 2,000 feet MSL, with wind there from 240° true at 40 knots.", "Wind shear is forecast at 2,400 feet AGL, with wind there from 020° true at 40 knots."], "explanation": "The height follows WS in hundreds of feet, followed by the wind direction and speed at that level.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "TAF low-level wind-shear group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 163, "category": "Weather", "difficulty": "Applied", "question": "What extra information does “150V220” add after a METAR wind group?", "answer": "The wind direction varied between 150° and 220° during the observation.", "distractors": ["The wind speed varied between 15 and 22 knots during the observation.", "Runway visual range varied between 1,500 and 2,200 feet.", "The wind was forecast to shift once from 150° to 220° after the observation."], "explanation": "The V group gives the observed directional extremes when the wind varies significantly.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR variable wind-direction group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 164, "category": "Weather", "difficulty": "Scenario", "question": "The temperature and dew point are converging near sunset while winds remain light. What condition should the remote pilot anticipate?", "answer": "An increasing chance of fog or low clouds as the air approaches saturation.", "distractors": ["The pilot should anticipate rapidly improving visibility as the air becomes drier.", "The pilot should anticipate thunderstorms solely because the temperature and dew point are close together.", "The pilot should anticipate strong, gusty surface wind caused by increasing temperature–dew-point spread."], "explanation": "A shrinking temperature–dew-point spread is a warning sign, especially when nighttime cooling is expected.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Moisture, saturation, fog, and low-cloud formation", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 165, "category": "Weather", "difficulty": "Scenario", "question": "Strong wind crosses a tree line before reaching the launch area. Where should the crew expect the roughest mechanical turbulence?", "answer": "On the downwind, or leeward, side of the tree line.", "distractors": ["The roughest turbulence should be expected only on the upwind side of the tree line.", "The roughest turbulence should be expected directly above the tree line, with smooth air immediately downwind.", "The tree line should not create turbulence because mechanical turbulence occurs only near mountains."], "explanation": "Airflow disrupted by buildings, trees, and terrain forms eddies that can persist well downwind of the obstruction.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Mechanical turbulence near surface obstructions", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 166, "category": "Weather", "difficulty": "Scenario", "question": "Strong wind is blowing nearly perpendicular to a mountain ridge. What hazard can develop on the ridge’s leeward side?", "answer": "Mountain-wave downdrafts and severe rotor turbulence can develop downwind of the ridge.", "distractors": ["A daytime sea breeze and smooth rising air can develop on the leeward side of the ridge.", "Radiation fog will form immediately because the ridge blocks all surface wind.", "Ground effect will increase sharply and eliminate downdrafts on the leeward side."], "explanation": "The airflow may oscillate after crossing the ridge, producing powerful vertical currents even in otherwise clear air.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Mountain waves and rotor turbulence", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 167, "category": "Weather", "difficulty": "Foundation", "question": "During a typical sunny afternoon, which way does a sea breeze blow?", "answer": "From the cooler water toward the warmer land.", "distractors": ["A sea breeze blows from the warmer land toward the cooler water.", "A sea breeze blows parallel to the shoreline with the coast on its left side.", "A sea breeze is an upper-level flow from land to water that does not affect the surface."], "explanation": "Land heats faster than water, encouraging rising air over land and an onshore surface flow.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Local winds — sea breeze", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 168, "category": "Weather", "difficulty": "Foundation", "question": "During a typical clear night, which way does a land breeze blow?", "answer": "From the cooler land toward the relatively warmer water.", "distractors": ["A land breeze blows from the relatively warmer water toward the cooler land.", "A land breeze blows parallel to the shoreline without crossing it.", "A land breeze flows upslope from coastal valleys toward higher terrain at night."], "explanation": "At night the land cools faster than water, reversing the pressure pattern that creates a daytime sea breeze.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Local winds — land breeze", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 169, "category": "Weather", "difficulty": "Foundation", "question": "How does surface wind circulate around a high-pressure system in the Northern Hemisphere?", "answer": "Clockwise and outward from the high.", "distractors": ["Surface wind circulates counterclockwise and inward toward a high-pressure center.", "Surface wind circulates clockwise and inward toward a high-pressure center.", "Surface wind circulates counterclockwise and outward from a high-pressure center."], "explanation": "Friction causes surface wind to cross the isobars slightly away from high pressure.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Northern Hemisphere pressure-system circulation", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 170, "category": "Weather", "difficulty": "Foundation", "question": "How does surface wind circulate around a low-pressure system in the Northern Hemisphere?", "answer": "Counterclockwise and inward toward the low.", "distractors": ["Surface wind circulates clockwise and outward from a low-pressure center.", "Surface wind circulates counterclockwise and outward from a low-pressure center.", "Surface wind circulates clockwise and inward toward a low-pressure center."], "explanation": "Friction weakens the Coriolis balance near the surface, so wind crosses the isobars toward lower pressure.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Northern Hemisphere pressure-system circulation", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 171, "category": "Weather", "difficulty": "Applied", "question": "What do tightly packed isobars usually indicate about surface wind?", "answer": "A strong pressure gradient and generally stronger wind.", "distractors": ["Tightly packed isobars indicate a weak pressure gradient and generally light wind.", "Tightly packed isobars indicate stable temperatures but reveal nothing about wind speed.", "Tightly packed isobars indicate that wind direction changes rapidly while speed remains low."], "explanation": "A larger pressure change across a shorter distance produces a greater force that accelerates the air.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Pressure-gradient force and isobars", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 172, "category": "Weather", "difficulty": "Applied", "question": "What weather is commonly found ahead of an approaching warm front?", "answer": "Widespread layered clouds, lowering ceilings, and steady precipitation may develop ahead of the front.", "distractors": ["Ahead of a warm front, skies usually clear rapidly as dry air arrives with gusty winds.", "Ahead of a warm front, weather is usually confined to a narrow line of brief thunderstorms at the surface boundary.", "Ahead of a warm front, high pressure normally produces cloudless skies and unrestricted visibility."], "explanation": "Warm air rises gradually over retreating cooler air, usually producing a broad area of stratiform weather.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Warm-front structure and weather", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 173, "category": "Weather", "difficulty": "Applied", "question": "Why can a stationary front disrupt drone operations for an extended period?", "answer": "Because the front moves little, clouds, poor visibility, wind shifts, and precipitation can persist over the same area.", "distractors": ["A stationary front disrupts operations because it normally crosses a site faster than either a warm or cold front.", "A stationary front disrupts operations because it immediately dissolves both adjoining air masses into clear weather.", "A stationary front changes surface pressure but cannot produce persistent clouds, precipitation, or visibility restrictions."], "explanation": "Neither air mass is advancing strongly enough to displace the boundary, so its weather may linger.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Stationary fronts", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 174, "category": "Weather", "difficulty": "Foundation", "question": "What creates an occluded front?", "answer": "A faster-moving cold front overtakes a warm front and lifts the warm air away from the surface.", "distractors": ["An occluded front forms when a warm front overtakes a cold front and forces the cold air away from the surface.", "An occluded front forms when two air masses stop moving and remain on opposite sides of a stationary boundary.", "An occluded front forms when two cold fronts merge without lifting any warm air from the surface."], "explanation": "Occlusion combines frontal structures and can produce extensive clouds and precipitation around the low-pressure system.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Occluded fronts", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 175, "category": "Weather", "difficulty": "Foundation", "question": "What conditions form advection fog?", "answer": "Warm, moist air moves over a colder surface and cools to its dew point.", "distractors": ["Advection fog forms when the ground cools rapidly beneath clear skies and calm wind overnight.", "Advection fog forms when moist air is forced up a mountain slope and cools as it rises.", "Advection fog forms when very cold air moves across much warmer water and receives moisture from below."], "explanation": "Unlike radiation fog, advection fog depends on horizontal air movement and can persist with moderate wind.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Advection fog", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 176, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What is the reciprocal runway number for Runway 09?", "answer": "Runway 27.", "distractors": ["The reciprocal runway number for Runway 09 is Runway 18.", "The reciprocal runway number for Runway 09 is Runway 36.", "The reciprocal runway number for Runway 09 remains Runway 09."], "explanation": "Opposite runway ends differ by 180°, so 090° becomes 270° and the designator changes from 09 to 27.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Runway designators", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 177, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What do the letters L, C, and R mean after runway numbers?", "answer": "They identify the left, center, and right runways in a parallel-runway group.", "distractors": ["The letters L, C, and R identify low-, category-, and regional-intensity runway lighting systems.", "The letters L, C, and R identify loose-, compacted-, and rigid-surface runway construction.", "The letters L, C, and R identify the landing, crossing, and rollout portions of one runway."], "explanation": "The letters distinguish runway surfaces that otherwise share the same magnetic-direction number.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Parallel-runway designators", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 178, "category": "Airport & Radio", "difficulty": "Applied", "question": "May an airplane land before the white threshold bar at a displaced threshold when approaching from that end?", "answer": "No; landing must begin at or beyond the displaced threshold.", "distractors": ["Yes; any paved surface before a displaced threshold is approved for touchdown from that end.", "Yes; touchdown before the displaced threshold is permitted whenever the landing occurs in daylight.", "Yes; an ATC landing clearance automatically authorizes touchdown before every displaced threshold."], "explanation": "The pavement before the bar may be used for takeoff in either direction and for landing rollout from the opposite direction, but not for touchdown from the displaced-threshold end.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Displaced-threshold markings", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 179, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What do large yellow chevrons on pavement aligned with a runway mean?", "answer": "That pavement is unusable for landing, takeoff, and taxiing.", "distractors": ["Large yellow chevrons mark a displaced threshold where touchdown is permitted after receiving clearance.", "Large yellow chevrons mark a taxiway shoulder that aircraft may use at reduced speed.", "Large yellow chevrons identify a closed runway that may still be used for taxiing."], "explanation": "Chevrons mark blast pads, stopways, or other paved areas that are not part of the usable movement surface.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Runway chevrons", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 180, "category": "Airport & Radio", "difficulty": "Foundation", "question": "Which colors distinguish standard runway markings from taxiway markings?", "answer": "Runway markings are white, while taxiway and holding-position markings are yellow.", "distractors": ["Runway markings are yellow, while taxiway and holding-position markings are white.", "Runway and taxiway markings are both yellow, with line width providing the only distinction.", "Runway markings are red, while taxiway and holding-position markings are white."], "explanation": "The color convention helps pilots identify the type and purpose of a paved movement area.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Airport pavement-marking colors", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 181, "category": "Airport & Radio", "difficulty": "Applied", "question": "Approaching a runway holding-position marking from the solid-line side, where must an aircraft stop?", "answer": "Stop before the solid lines. At a towered airport, cross only with ATC clearance; at a non-towered airport, cross only after ensuring adequate separation.", "distractors": ["The aircraft must cross the solid lines and stop immediately before the dashed lines.", "The aircraft may cross the marking without clearance whenever normal radio communication is available.", "The aircraft must stop only when approaching from the dashed-line side of the marking."], "explanation": "No part of the aircraft may extend beyond the marking while holding; non-towered crossing requires separation from aircraft, vehicles, and pedestrians.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Runway holding-position markings", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 182, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What do blue lights identify at an airport at night?", "answer": "Taxiway edges.", "distractors": ["Blue lights identify runway edges.", "Blue lights identify taxiway centerlines.", "Blue lights identify the approach threshold of a runway."], "explanation": "Blue edge lights distinguish taxiways from runways and other paved areas.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Taxiway edge lights", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_1.html"}},
  {"id": 183, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What do steady green lights along a paved route identify?", "answer": "A taxiway centerline.", "distractors": ["Steady green lights along a paved route identify a runway centerline.", "Steady green lights along a paved route identify taxiway edges.", "Steady green lights along a paved route identify the final approach path to a runway."], "explanation": "Green centerline lights help aircraft remain aligned on taxiways in darkness or reduced visibility.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Taxiway centerline lights", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_1.html"}},
  {"id": 184, "category": "Airport & Radio", "difficulty": "Applied", "question": "What do yellow runway edge lights near the far end of an instrument runway warn a pilot about?", "answer": "The aircraft is entering the runway’s caution zone and approaching the runway end.", "distractors": ["Yellow runway edge lights warn that the aircraft is approaching a displaced threshold at the runway's beginning.", "Yellow runway edge lights identify an upcoming taxiway intersection where turns are permitted.", "Yellow runway edge lights indicate that the remaining runway is closed to all aircraft movement."], "explanation": "On instrument runways, edge lights are yellow for the last 2,000 feet or half the runway length, whichever is less.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Runway edge-light caution zone", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_1.html"}},
  {"id": 185, "category": "Airport & Radio", "difficulty": "Applied", "question": "What does a four-light PAPI showing two white and two red lights indicate?", "answer": "The aircraft is on the proper glide path.", "distractors": ["Two white and two red PAPI lights indicate that the aircraft is above the proper glide path.", "Two white and two red PAPI lights indicate that the aircraft is below the proper glide path.", "Two white and two red PAPI lights indicate that the PAPI system is out of service."], "explanation": "More white lights indicate a path above the glide path; more red lights indicate a path below it.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Precision approach path indicator", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_1.html"}},
  {"id": 186, "category": "Airport & Radio", "difficulty": "Applied", "question": "What is the purpose of runway end identifier lights (REIL)?", "answer": "They help pilots rapidly identify the approach end of a runway.", "distractors": ["Runway end identifier lights identify the departure end of a runway after takeoff.", "Runway end identifier lights mark the runway centerline throughout its full length.", "Runway end identifier lights provide vertical glide-path guidance during final approach."], "explanation": "A REIL system uses synchronized flashing lights on each side of the runway threshold, making the runway end more conspicuous.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Runway end identifier lights", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_1.html"}},
  {"id": 187, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What information does an ATIS broadcast provide?", "answer": "A continuous broadcast of recorded noncontrol terminal information, including current weather, approaches and runways in use, and pertinent notices.", "distractors": ["An ATIS broadcast provides individual takeoff, landing, and taxi clearances to each aircraft.", "An ATIS broadcast is reserved for distress calls and airport emergency coordination.", "An ATIS broadcast provides nationwide en route forecasts but no local airport information."], "explanation": "Pilots use the broadcast to receive common airport information before contacting the controller.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "§ 4-1-13 — Automatic Terminal Information Service", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_1.html"}},
  {"id": 188, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What is a UNICOM station at a non-towered airport?", "answer": "A nongovernment communication station that may provide airport advisories and services but does not issue ATC clearances.", "distractors": ["A UNICOM station is an FAA air traffic control facility that issues binding taxi and landing clearances.", "A UNICOM station is an automated weather sensor that cannot provide airport services or advisories.", "A UNICOM station is the emergency-frequency service used only for distress and urgency calls."], "explanation": "UNICOM information can improve awareness, but the pilot remains responsible for traffic avoidance and safe operation.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "§§ 4-1-9 through 4-1-12 — UNICOM communications", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_1.html"}},
  {"id": 189, "category": "Airport & Radio", "difficulty": "Foundation", "question": "Which VHF frequency is the civil aviation emergency frequency?", "answer": "121.5 MHz.", "distractors": ["The civil aviation emergency frequency is 122.8 MHz.", "The civil aviation emergency frequency is 123.0 MHz.", "The civil aviation emergency frequency is 243.0 MHz."], "explanation": "The frequency is monitored for distress and urgency communications; it is not for routine conversation.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "§ 6-3-1 — emergency frequencies", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap6_section_3.html"}},
  {"id": 190, "category": "Airport & Radio", "difficulty": "Applied", "question": "What does a steady red tower light signal mean to an aircraft on the ground?", "answer": "Stop.", "distractors": ["A steady red tower light authorizes an aircraft on the ground to taxi across the airport.", "A steady red tower light directs an aircraft on the ground to return to its starting point.", "A steady red tower light clears an aircraft on the ground for takeoff."], "explanation": "Tower light-gun signals provide standardized visual instructions when normal radio communication is unavailable.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Airport traffic control tower light-gun signals", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_3.html"}},
  {"id": 191, "category": "Performance & Loading", "difficulty": "Foundation", "question": "In weight-and-balance calculations, what is an item’s arm?", "answer": "Its horizontal distance from the aircraft’s reference datum.", "distractors": ["An item's arm is the item's weight measured at the aircraft reference datum.", "An item's arm is the turning moment created by that item about the datum.", "An item's arm is the allowable center-of-gravity range published for the aircraft."], "explanation": "The datum is the manufacturer-defined reference plane from which arms are measured.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Weight-and-balance terminology — arm and datum", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 192, "category": "Performance & Loading", "difficulty": "Foundation", "question": "How is an item’s moment calculated for weight and balance?", "answer": "Multiply the item’s weight by its arm.", "distractors": ["Calculate an item's moment by dividing its weight by its arm.", "Calculate an item's moment by adding its weight to its arm.", "Calculate an item's moment by multiplying its arm by the square of its weight."], "explanation": "Moment represents the item’s turning effect about the datum and is commonly expressed in pound-inches.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Weight-and-balance terminology — moment", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 193, "category": "Performance & Loading", "difficulty": "Foundation", "question": "How is the loaded aircraft’s center of gravity calculated from total weight and total moment?", "answer": "Divide total moment by total weight.", "distractors": ["Calculate the loaded center of gravity by dividing total weight by total moment.", "Calculate the loaded center of gravity by adding total weight and total moment.", "Calculate the loaded center of gravity by averaging all item arms without weighting them."], "explanation": "The resulting arm must fall within the manufacturer’s approved center-of-gravity limits.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Center-of-gravity calculation", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 194, "category": "Performance & Loading", "difficulty": "Applied", "question": "A 2-pound payload is mounted at an arm of 12 inches. What moment does it add?", "answer": "It adds 24 pound-inches of moment.", "distractors": ["The payload adds 6 pound-inches of moment.", "The payload adds 14 pound-inches of moment.", "The payload adds 10 pound-inches of moment."], "explanation": "Moment equals weight multiplied by arm: 2 lb × 12 in = 24 lb-in.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Moment calculation", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 195, "category": "Performance & Loading", "difficulty": "Scenario", "question": "An 8-pound aircraft has a 40 pound-inch moment. A 2-pound payload adds 30 pound-inches. What is the combined center-of-gravity arm?", "answer": "The combined center-of-gravity arm is 7 inches from the datum.", "distractors": ["The combined center-of-gravity arm is 5 inches from the datum.", "The combined center-of-gravity arm is 8.75 inches from the datum.", "The combined center-of-gravity arm is 35 inches from the datum."], "explanation": "Add the moments and weights, then divide: (40 + 30) lb-in ÷ (8 + 2) lb = 7 in.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Combined center-of-gravity calculation", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 196, "category": "Performance & Loading", "difficulty": "Applied", "question": "If a payload’s weight stays the same but it is moved farther from the datum, what happens to its moment?", "answer": "The magnitude of its moment increases in direct proportion to its distance from the datum; the sign depends on which side of the datum the payload is located.", "distractors": ["Its moment always becomes more positive in direct proportion to the greater arm, regardless of which side of the datum it is on.", "Its moment remains unchanged because the payload's weight did not change.", "Its moment becomes zero whenever the payload is moved farther from the datum."], "explanation": "Moment equals weight times signed arm. Greater distance increases leverage, while a forward or negative arm produces a more-negative moment.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Effect of changing an item’s arm", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 197, "category": "Performance & Loading", "difficulty": "Applied", "question": "How does increasing weight affect the stall speed of a fixed-wing small UAS?", "answer": "It increases the stall speed.", "distractors": ["Increasing weight decreases the stall speed of a fixed-wing small UAS.", "Increasing weight has no effect on stall speed if the wing configuration remains unchanged.", "Increasing weight affects stall speed only during a banked turn, not during level flight."], "explanation": "A heavier fixed-wing aircraft must produce more lift; at the same configuration and load factor, it reaches the critical angle of attack at a higher airspeed.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Weight, lift requirements, and stall speed", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 198, "category": "Performance & Loading", "difficulty": "Applied", "question": "What load factor does an aircraft experience in a coordinated, level 60° bank?", "answer": "A load factor of 2 G.", "distractors": ["The aircraft experiences a load factor of 1 G in a coordinated, level 60-degree bank.", "The aircraft experiences a load factor of 1.5 G in a coordinated, level 60-degree bank.", "The aircraft experiences a load factor of 3 G in a coordinated, level 60-degree bank."], "explanation": "At 60° of bank, the aircraft must produce lift equal to twice its weight to maintain altitude.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Bank angle and load factor", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 199, "category": "Performance & Loading", "difficulty": "Scenario", "question": "A drone’s maximum takeoff weight is 8.8 pounds. It weighs 6.2 pounds empty, and required accessories add 0.4 pound. What is the greatest remaining payload allowed by that limit?", "answer": "The remaining payload allowance is 2.2 pounds.", "distractors": ["The greatest remaining payload allowed is 2.6 pounds.", "The greatest remaining payload allowed is 1.8 pounds.", "The greatest remaining payload allowed is 15.4 pounds."], "explanation": "Subtract the configured aircraft weight from the limit: 8.8 − 6.2 − 0.4 = 2.2 pounds.", "source": {"label": "FAA AC 107-2A", "reference": "Aircraft limitations and mission loading", "url": "https://www.faa.gov/regulations_policies/advisory_circulars/index.cfm/go/document.information/documentID/1038977"}},
  {"id": 200, "category": "Performance & Loading", "difficulty": "Scenario", "question": "A battery provides 24 minutes of usable flight time in the planned conditions. If the pilot reserves 25% for contingencies, what is the maximum planned flight time?", "answer": "The planned flight should be no longer than 18 minutes.", "distractors": ["The maximum planned flight time is 6 minutes.", "The maximum planned flight time is 20 minutes.", "The maximum planned flight time is 16 minutes."], "explanation": "A 25% reserve is 6 minutes, leaving 18 minutes for the planned mission; actual limits and reserve policy should be more conservative when conditions warrant.", "source": {"label": "FAA AC 107-2A", "reference": "Available power and contingency reserves", "url": "https://www.faa.gov/regulations_policies/advisory_circulars/index.cfm/go/document.information/documentID/1038977"}},
  {"id": 201, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Under current FAA safety-management definitions, how does a hazard differ from risk?", "answer": "A hazard is a condition or object that could foreseeably cause or contribute to an incident or aircraft accident; risk combines the predicted severity and likelihood of the hazard’s potential effect.", "distractors": ["A hazard is the measured likelihood and severity of harm, while risk is the condition that can cause it.", "A hazard and risk are interchangeable terms for any unsafe condition.", "A hazard is the numerical score on a risk matrix, while risk is the physical source of danger."], "explanation": "The hazard is the source of a possible adverse effect; risk combines how severe that effect could be with how likely it is.", "source": {"label": "14 CFR § 5.3", "reference": "14 CFR § 5.3 — hazard and risk", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-A/part-5/subpart-A/section-5.3"}},
  {"id": 202, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What is the first step in a small-UAS safety risk assessment?", "answer": "Identify the hazards associated with the aircraft, crew, environment, and planned operation.", "distractors": ["The first step is to assign every possible event a numerical risk score.", "The first step is to select mitigations before identifying what could go wrong.", "The first step is to launch under controlled conditions and use the results as the baseline assessment."], "explanation": "A risk rating is meaningful only after the crew states what could go wrong and why.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.2.4 — Developing Risk Assessment Skills", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 203, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which two factors are combined to assign a risk level to an identified hazard?", "answer": "The likelihood that the hazard will occur and the severity of its consequences.", "distractors": ["A risk level combines the duration of exposure with the time available for recovery.", "A risk level combines the mission's financial cost with its schedule priority.", "A risk level combines hazard detectability with the pilot's confidence in the mission."], "explanation": "A risk matrix combines probability and consequence instead of treating every hazard as equally urgent.", "source": {"label": "FAA Risk Management Handbook", "reference": "Chapter 4 — Using a Risk Assessment Matrix", "url": "https://www.faa.gov/sites/faa.gov/files/2022-06/risk_management_handbook_2A.pdf"}},
  {"id": 204, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "When a pilot is unsure between two likelihood or severity ratings, which rating should be used?", "answer": "Use the more conservative rating, which places the hazard at the higher risk level.", "distractors": ["Use the less conservative rating so one uncertain factor does not cancel the mission.", "Average the two ratings and round the result down to the lower risk level.", "Repeat the assessment until both ratings fall into the same lower category."], "explanation": "Optimistic inputs can hide risk; the FAA handbook advises conservative parameters when the assessment is uncertain.", "source": {"label": "FAA Risk Management Handbook", "reference": "Chapter 4 — Risk Matrix Errors: Accuracy", "url": "https://www.faa.gov/sites/faa.gov/files/2022-06/risk_management_handbook_2A.pdf"}},
  {"id": 205, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "A preflight matrix rates a mission hazard as serious or high. What must happen before launch?", "answer": "Do not launch unless controls reduce the hazard to an acceptable risk level.", "distractors": ["The mission may launch as planned if a visual observer acknowledges the serious or high rating.", "The remote PIC may accept a serious or high rating without mitigation by documenting it before launch.", "The mission should launch and the crew should record whether the serious or high hazard actually occurs."], "explanation": "Serious and high ratings imply a no-go decision until effective mitigation changes the assessment.", "source": {"label": "FAA Risk Management Handbook", "reference": "Chapter 4 — risk-level decisions", "url": "https://www.faa.gov/sites/faa.gov/files/2022-06/risk_management_handbook_2A.pdf"}},
  {"id": 206, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What is residual risk?", "answer": "Residual risk is the risk that remains after the planned controls have been applied.", "distractors": ["Residual risk is a new hazard created by a proposed safety control.", "Residual risk is the original risk level calculated before any controls are selected.", "Residual risk is the portion of the original risk that the controls have completely eliminated."], "explanation": "A control rarely eliminates every consequence, so the remaining exposure must still be judged acceptable.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.10 — Residual and Substitute Risk", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 207, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What is substitute risk when evaluating a proposed safety control?", "answer": "It is a new hazard introduced by the control—potentially making the solution worse than the original problem.", "distractors": ["Substitute risk is the exposure that remains after an effective control has been applied.", "Substitute risk is the original risk score assigned before any mitigation is considered.", "Substitute risk is a financial loss transferred from the operator to an insurer."], "explanation": "Every mitigation must be checked both for effectiveness and for new failure paths it creates.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.10 — Residual and Substitute Risk", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 208, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "How can a risk mitigation lower the overall risk of a hazard?", "answer": "It can reduce the likelihood of the hazard, reduce the severity of the outcome, or reduce both.", "distractors": ["A mitigation lowers risk by reducing the number written in the assessment without changing the hazard.", "A mitigation lowers risk whenever more controls are added, even if none affects likelihood or severity.", "A mitigation lowers risk by moving the hazard into a different category while leaving the exposure unchanged."], "explanation": "Specific controls should identify which part of the risk they change rather than merely claim that the flight is safer.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.4 — Formulating Mitigations", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 209, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "Why should a crew identify the root cause of a hazard instead of relying only on its risk score?", "answer": "The root cause shows what must be changed to create an effective risk control.", "distractors": ["The numerical risk score already identifies the needed control, so finding the root cause adds no useful information.", "The crew should control the highest-rated symptom even when that action does not address why the hazard exists.", "Removing the first visible symptom is sufficient even if the underlying condition remains unchanged."], "explanation": "Severity and likelihood describe exposure; root-cause analysis directs the crew toward controls that address why the hazard exists.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.7 — Reducing Risk", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 210, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "Why should a remote pilot establish personal minimums before accepting a mission?", "answer": "They create predetermined limits based on the pilot’s experience, proficiency, health, and tolerance for risk.", "distractors": ["Personal minimums replace Part 107 limits whenever the pilot has more restrictive preferences.", "Personal minimums provide the airspace authorization needed to operate in controlled airspace.", "Personal minimums guarantee that a mission has no residual risk once the pilot accepts it."], "explanation": "Limits chosen before schedule or customer pressure appears are less likely to be weakened by a desire to complete the job.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — PAVE and personal minimums", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 211, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What should a mission briefing define about conditions that would make the flight unsafe to continue?", "answer": "It should define clear stop or discontinuation criteria and identify who will make and execute the decision.", "distractors": ["A mission briefing should define only the planned route and leave stop decisions to in-flight judgment.", "A mission briefing should define the customer's completion criteria as the only reason to discontinue.", "A mission briefing should define an exact launch time but avoid assigning authority to stop the flight."], "explanation": "Predefined triggers prevent hesitation and debate after the crew is already under pressure.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.4 — Formulating Mitigations", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 212, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "The wind, pedestrian activity, and crew workload all increase during a flight. What should the remote PIC do with the original risk assessment?", "answer": "Reassess it using the current conditions and change, pause, or end the operation if the risk is no longer acceptable.", "distractors": ["The remote PIC should keep the original assessment because changing it in flight would make the preflight matrix invalid.", "The remote PIC should ignore the increases unless a published Part 107 limit has already been exceeded.", "The remote PIC should wait until the post-flight debrief to decide whether the increased hazards were acceptable."], "explanation": "A preflight score becomes obsolete when hazards change; risk management continues throughout the flight.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.1 — In-Flight Mitigations", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 213, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What two actions does FAA guidance recommend after a flight to improve future risk decisions?", "answer": "Conduct a thorough debrief and capture lessons learned and recommendations.", "distractors": ["After flight, the crew should discard the original assessment and avoid recording unexpected events.", "After flight, the crew should update only flight-time totals because risk decisions belong exclusively in preflight planning.", "After flight, the crew should immediately repeat the mission before conditions change so the original assessment remains valid."], "explanation": "Recording what worked, what failed, and what was unexpected converts one mission’s experience into safer future planning.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.2 — Post-Flight", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 214, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "One crewmember is simultaneously watching the drone, monitoring traffic, answering bystanders, and tracking battery status. What is the proper CRM response?", "answer": "Reallocate the tasks, add sufficient crewmembers, or pause the operation before the person becomes overloaded.", "distractors": ["The crewmember should continue all assigned tasks because switching roles creates more risk than high workload.", "The crew should remove the visual observer and transfer every monitoring task to the remote PIC.", "The crew should enable more automation and continue without reassessing whether anyone can monitor it safely."], "explanation": "FAA guidance links excessive workload to a greater possibility of an incident or accident.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.2.5.3 — Task Management", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 215, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "When should the crew choose and test its communication method?", "answer": "Before flight, using a method everyone can understand that does not create a distraction.", "distractors": ["The crew should choose and test its communication method only after takeoff reveals the site's actual noise level.", "The crew should choose a communication method only for emergencies, not for routine coordination.", "The crew should wait until a communication problem occurs and then select a method while the aircraft remains airborne."], "explanation": "The best method depends on the site, separation, noise, and equipment; discovering that it fails after launch is too late.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.2.5.2 — Communication Methods", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 216, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What operational information should a visual observer report to the remote PIC?", "answer": "The drone’s location and flight state, nearby aircraft or hazards, and any developing danger to people or property.", "distractors": ["The visual observer should report only battery percentage and leave aircraft position and hazards to the remote PIC.", "The visual observer should report forecast weather changes but not nearby aircraft or people on the surface.", "The visual observer should issue air traffic control instructions to nearby aircraft instead of reporting conflicts to the remote PIC."], "explanation": "A useful observer call gives the pilot actionable information, not merely confirmation that the drone is visible.", "source": {"label": "FAA AC 107-2A", "reference": "¶ 5.9.2 — Visual Observer", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 217, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "Construction equipment unexpectedly blocks the planned recovery route. What crew-coordination step should follow the remote PIC’s revised plan?", "answer": "Brief the crew on the changed conditions, the new flight profile, and each needed adjustment before continuing.", "distractors": ["The remote PIC should change the plan silently so the crew is not distracted by another briefing.", "The visual observer should continue following the original recovery plan while the remote PIC uses the revised route.", "The crew should continue the mission and discuss the revised profile only during the post-flight debrief."], "explanation": "A safe plan change can fail if the observer or control manipulator continues acting on the original briefing.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶¶ A.2.5.1 and A.4.1 — changing conditions", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 218, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What control capability must the remote PIC retain during an automated waypoint mission?", "answer": "The ability to change the route or altitude, avoid a hazard, and command the aircraft to land immediately.", "distractors": ["The remote PIC may surrender all control until the waypoint sequence is complete.", "The remote PIC needs only the ability to pause the camera payload during an automated mission.", "The remote PIC may rely solely on an automatic return-to-home command and does not need to redirect or land the aircraft."], "explanation": "Automation flies programmed inputs, but it does not replace the remote PIC’s authority or responsibility to redirect the aircraft.", "source": {"label": "FAA AC 107-2A", "reference": "¶ 5.2.3 — Automated Operations", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 219, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What practices help keep complacency and overconfidence from degrading a routine operation?", "answer": "Use the same checklists and structured decision model, and actively verify current conditions even when the mission feels familiar.", "distractors": ["Routine missions should omit written checklists because repetition makes each item automatic.", "The crew should rely on automation to detect changed conditions instead of repeating structured checks.", "After each uneventful flight, the crew should shorten the checklist until it covers only unusual conditions."], "explanation": "Repetition can create false confidence; disciplined checks preserve awareness of changes and missed details.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.2.6 — Evaluating ADM Skills", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 220, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "A pilot expects stress from an inexperienced observer, public questions, and unfamiliar site officials. What is the best preflight response?", "answer": "Plan roles, communication, public interaction, and contingencies in advance so those stressors do not consume attention in flight.", "distractors": ["The pilot should wait until launch and improvise roles as each stressor appears.", "The pilot should assign all public interaction to the visual observer without reducing that observer's flight-monitoring duties.", "The pilot should shorten the planned flight but leave crew roles, communication, and contingencies undefined."], "explanation": "FAA guidance identifies these as small-UAS stressors and notes that proper planning can reduce or eliminate their effect.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.2.3 — Recognize and Cope with Stress", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 221, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "A remote pilot is acutely fatigued before launch after a night of poor sleep. What is the safe decision?", "answer": "Do not operate; obtain adequate rest before flying.", "distractors": ["The pilot may fly a shorter mission because reducing duration offsets acute fatigue.", "The pilot may continue after asking the visual observer to watch for fatigue-related mistakes.", "The pilot may launch if the aircraft's automation can complete most of the route."], "explanation": "Training and experience do not overcome fatigue’s effects on attention, timing, coordination, and decision-making.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 9 — Acute Fatigue", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 222, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "How does chronic fatigue differ from ordinary short-term fatigue, and what action does FAA guidance recommend?", "answer": "Chronic fatigue persists over a long period and is not relieved by proper diet, rest, and sleep; a remote pilot who suspects it should consult a physician.", "distractors": ["Chronic fatigue normally disappears after one short nap and does not require further evaluation.", "Chronic fatigue is always a normal circadian low that resolves at the same time each day.", "Chronic fatigue has the same short duration as ordinary fatigue and is corrected by completing a shorter flight."], "explanation": "Long-term stress or an underlying illness may be involved, so a single good night of sleep is not an adequate remedy.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 9 — Chronic Fatigue", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 223, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "Why should a remote pilot hydrate regularly during a hot mission instead of waiting to feel thirsty?", "answer": "Thirst can occur after meaningful dehydration has already reduced physical and mental performance.", "distractors": ["Thirst reliably occurs before dehydration can affect physical or mental performance.", "The pilot should drink only before launch and after landing because in-flight thirst is not an operational concern.", "The pilot should use thirst alone to schedule fluids because it precisely tracks current hydration status."], "explanation": "Headache, fatigue, cramps, sleepiness, and dizziness are warning signs; staying ahead of thirst is the safer control.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 9 — Dehydration", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 224, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "Under stress, a pilot becomes dizzy, feels tingling, and realizes they are breathing rapidly. What immediate action addresses likely hyperventilation?", "answer": "Slow the breathing rate and breathe normally; talking aloud can also help restore a normal pattern.", "distractors": ["The pilot should deliberately breathe faster to increase oxygen intake until the tingling stops.", "The pilot should breathe into a paper bag while continuing the operation at the same workload.", "The pilot should use supplemental oxygen but allow the rapid breathing pattern to continue unchanged."], "explanation": "Hyperventilation removes excessive carbon dioxide and can worsen as anxiety increases, so controlled breathing breaks the cycle.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 9 — Hyperventilation", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 225, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "A pilot took a new over-the-counter antihistamine and is unsure whether it causes drowsiness. May the pilot launch before completing the required checks and wait interval?", "answer": "Do not fly; identify the active ingredient, complete at least a 48-hour initial ground trial, and follow any longer medication-specific no-fly interval.", "distractors": ["Yes; over-the-counter medications are presumed safe for flight without testing their effects.", "Yes; the pilot may launch if the package lacks an explicit aviation warning, even when drowsiness is uncertain.", "Yes; taking half the labeled dose guarantees that the antihistamine cannot impair performance."], "explanation": "Sedating antihistamines are no-go medications; for example, current FAA guidance requires 60 hours after the last dose of diphenhydramine.", "source": {"label": "FAA OTC Medication Guidance", "reference": "48-hour ground trial and antihistamine no-fly guidance", "url": "https://www.faa.gov/ame_guide/media/AME_OTC_medications.pdf"}},
  {"id": 226, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A waiver authorizes BVLOS flight only within a defined corridor. May the operator fly outside that corridor or disregard unrelated Part 107 rules?", "answer": "No. The operator may deviate only from the provisions specified in the waiver and must obey every waiver condition and all other applicable rules.", "distractors": ["Yes; the corridor in a BVLOS waiver is advisory and may be exceeded whenever visual contact is regained.", "Yes; remaining below 400 feet allows the operator to ignore the waiver corridor and unrelated Part 107 rules.", "Yes; any BVLOS waiver suspends all Part 107 provisions for the duration of the authorized operation."], "explanation": "A waiver is limited authorization, not a general exemption from Part 107.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.200(d) — waiver scope and conditions", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 227, "category": "Operations & Safety", "difficulty": "Applied", "question": "Besides weather and airspace, what surface information belongs in the required operating-environment assessment?", "answer": "The locations of people and property on the surface, plus other ground hazards in the operating area.", "distractors": ["The assessment needs only satellite coverage and magnetic-interference data for the planned route.", "The assessment needs only the certificates and training records of participating crewmembers.", "The assessment needs only the airspace class at the aircraft's planned maximum altitude."], "explanation": "The remote PIC must evaluate both airborne conflicts and the consequences of an abnormal landing or falling object.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(a)(3)–(4)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 228, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A public walkway borders the worksite. What contingency should be planned before launch?", "answer": "Define how the crew will detect and respond if nonparticipants or moving vehicles enter the operational area.", "distractors": ["The crew may rely on asking pedestrians to leave only after they enter the operational area.", "No intrusion contingency is needed because the walkway is outside the exact takeoff point.", "The crew may continue over people or moving vehicles that enter the area as long as the drone remains below 400 feet."], "explanation": "The plan may use an observer, barriers, a pause call, rerouting, or landing, but the response must be briefed before the intrusion occurs.", "source": {"label": "FAA AC 107-2A", "reference": "¶ 5.11.1 — preflight contingency for people and vehicles", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 229, "category": "Operations & Safety", "difficulty": "Applied", "question": "Which ground locations should be checked for suitability during practical mission planning?", "answer": "The control-station location, takeoff and landing sites, and emergency or alternate landing areas.", "distractors": ["Only the primary takeoff point needs a suitability check before the mission.", "The crew should check nearby airport runways instead of control-station and emergency landing locations.", "The crew should check property boundaries only, because landing-area suitability can be decided after launch."], "explanation": "A technically legal route can still be unsafe if the crew lacks a protected place to control, launch, recover, or divert the aircraft.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix E — Sample Preflight Assessment and Inspection Checklist, item 7", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 230, "category": "Operations & Safety", "difficulty": "Scenario", "question": "You are filming near an emergency scene, and the primary landing area might be needed by an EMS helicopter. What should the mission plan include?", "answer": "An alternate landing site—and, if necessary, a predetermined sacrificial area that protects people and manned aircraft.", "distractors": ["The mission should reserve the primary landing area exclusively for the drone even if an EMS helicopter arrives.", "The drone should hover until the EMS helicopter departs rather than use an alternate landing site.", "The mission should designate the nearest public road as the automatic landing site during any emergency."], "explanation": "Planning the escape before launch prevents low battery and a suddenly occupied recovery area from forcing a dangerous choice.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.8.1 — alternate landing-site example", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 231, "category": "Operations & Safety", "difficulty": "Scenario", "question": "What potential consequence must a remote PIC understand if GPS is lost during flight?", "answer": "GPS-dependent navigation and position functions may degrade or become unavailable, so the aircraft may not hold position or complete automated navigation as expected.", "distractors": ["GPS loss affects only the map display; position hold and automated route functions remain fully reliable.", "Only video quality is affected; navigation and position functions cannot be affected by loss of GPS.", "The aircraft automatically gains a more accurate inertial position and stronger return-to-home capability."], "explanation": "The exact response is aircraft-specific; the pilot must know the manufacturer’s loss-of-GPS behavior and prebrief a safe contingency.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area V, Task C, UA.V.C.K4 — loss of GPS signal and consequences", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 232, "category": "Operations & Safety", "difficulty": "Applied", "question": "Why can dense Wi-Fi and Bluetooth activity near offices or housing threaten a small-UAS mission?", "answer": "Those signals may share common control bands and interfere with the command link, contributing to loss of control or a flyaway.", "distractors": ["Dense Wi-Fi and Bluetooth activity can reduce GPS accuracy but cannot affect the radio command link.", "Frequency-hopping control systems are immune to congestion from nearby Wi-Fi and Bluetooth devices.", "Dense Wi-Fi and Bluetooth activity can disrupt the video downlink but never the command uplink."], "explanation": "The crew should assess local radio-frequency congestion and follow the aircraft manufacturer’s frequency guidance.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, Figure A-2 — Wi-Fi/Bluetooth control-link interference", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 233, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A concrete building moves between the control station and the drone. What control-link risk does this create?", "answer": "The barrier can weaken or block the line-of-sight radio-frequency link, causing delayed commands or loss of control.", "distractors": ["A concrete building normally amplifies the command signal and improves control-link reliability.", "A concrete building affects only the pilot's visual view and cannot attenuate a radio-frequency link.", "A concrete building triggers a GPS geofence but has no effect on delayed or lost control commands."], "explanation": "Many 2.4 GHz and 5.8 GHz small-UAS links depend on a clear radio path even when the pilot has planned visual-line-of-sight coverage.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix B, ¶ B.6.1.2 — RF line-of-sight limitations", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 234, "category": "Operations & Safety", "difficulty": "Scenario", "question": "Control inputs become delayed or no longer match aircraft response during a systems check. What should happen next?", "answer": "Stop the flight or avoid launch until the control link has been inspected, tested, and shown to be reliable.", "distractors": ["Continue the mission if the drone remains in visual line of sight despite delayed controls.", "Increase altitude and complete the mission so the command link has a clearer path.", "Reboot the controller while the aircraft remains airborne and resume the route immediately."], "explanation": "Unsynchronized control response can precede a collision, flyaway, or complete loss of control.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, condition 8", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 235, "category": "Operations & Safety", "difficulty": "Applied", "question": "What controlled flight check can reveal site-specific interference before committing to the mission route?", "answer": "At low altitude, fly within the expected interference area and recheck control response and stability.", "distractors": ["Fly to the site's maximum legal altitude and test the link at the edge of its advertised range.", "Switch off the controller briefly and verify that the aircraft's failsafe can recover the link.", "Hover behind the largest obstruction until the aircraft is out of sight and check whether commands still work."], "explanation": "The check should remain controlled and conservative; abnormal response means the mission should not continue until resolved.", "source": {"label": "FAA AC 107-2A", "reference": "¶ 7.3.4 and Appendix E — low-altitude control and stability check", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 236, "category": "Operations & Safety", "difficulty": "Foundation", "question": "What conditions can initiate a lithium flight-battery fire?", "answer": "Short circuit, improper charging, extreme heat, crash damage, mishandling, or an internal defect.", "distractors": ["A lithium flight-battery fire can begin only when a charger raises the indicated charge above 100 percent.", "A lithium flight-battery fire can begin during charging but not while the battery is stored or installed in the aircraft.", "A damaged lithium battery becomes safe to use once it cools back to room temperature."], "explanation": "Lithium-based batteries are highly flammable, so safe handling must cover charging, storage, transport, and post-crash inspection.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix B, ¶ B.5 — Battery Fires", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 237, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A flight battery has a visibly bulging casing. May it be used because it still reaches full indicated charge?", "answer": "No; remove it from service and have its integrity evaluated under manufacturer guidance.", "distractors": ["Yes; the battery may be used if a capacity test and voltage reading remain within limits.", "Yes; discharging the battery to its storage voltage makes a swollen casing safe for another flight.", "Yes; one slow balance-charge cycle can restore the battery to service if the swelling does not increase."], "explanation": "Bulging can indicate impending abrupt power loss, explosion, fire, or extreme heat; the charge display does not prove safety.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, condition 9", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 238, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A battery that once supported 22-minute missions now reaches the same reserve in 13 minutes. What should the operator infer?", "answer": "The battery may be near the end of its service life or damaged and should be inspected before further use.", "distractors": ["The shorter endurance shows only that the reserve indicator has become more conservative, so no inspection is needed.", "The shorter endurance proves that a firmware update has permanently reduced the mission timer but not battery capacity.", "The shorter endurance indicates lower internal resistance and greater remaining service life."], "explanation": "Diminishing endurance is a reliability warning, not merely a reason to shorten the planned route.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, condition 10", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 239, "category": "Operations & Safety", "difficulty": "Applied", "question": "When traveling by passenger aircraft, how must spare lithium flight batteries be carried and protected?", "answer": "Carry them in carry-on baggage, protect each battery individually against short circuit, and follow applicable battery-size and quantity limits.", "distractors": ["Pack spare batteries loose together in a metal container so any heat can dissipate quickly.", "Stack spare batteries together without terminal covers as long as every battery is at storage voltage.", "Place all spare batteries in one soft bag without individually isolating their terminals."], "explanation": "Spare lithium batteries are not permitted in checked baggage; original packaging, terminal tape, or a separate protective pouch can prevent short circuits.", "source": {"label": "FAA SAFO 15010", "reference": "Recommended action — individual short-circuit protection", "url": "https://www.faa.gov/sites/faa.gov/files/2022-11/15010_SAFO.pdf"}},
  {"id": 240, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A charger profile does not match the flight-battery type specified by the manufacturer. Should charging continue?", "answer": "No; stop and use the manufacturer-recommended charging method and settings.", "distractors": ["Yes; charging may continue because a modern charger automatically corrects every incompatible profile.", "Yes; selecting a lower current makes any mismatched battery profile safe.", "Yes; continuous visual monitoring eliminates the fire risk from an incompatible charging method."], "explanation": "Improper charging is a recognized cause of lithium-battery ignition, so convenience does not justify an unverified profile.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix B, ¶ B.5 — Battery Fires", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 241, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A preflight inspection reveals a hairline airframe crack or bonded-surface delamination. What is the proper response?", "answer": "Do not fly until the scope, hidden damage, structural integrity, and required repair have been evaluated.", "distractors": ["Cover the crack or delamination with tape and fly if the aircraft passes a power-on check.", "Treat the damage as cosmetic until it grows enough to alter the aircraft's handling.", "Perform a brief hover test and return the aircraft to service without evaluating hidden structural damage."], "explanation": "Small visible damage can extend into a load-bearing structure and compromise the aircraft under vibration or maneuvering loads.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, conditions 1 and 2", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 242, "category": "Operations & Safety", "difficulty": "Scenario", "question": "During power-up, the crew smells electrical burning and sees a soot trace near a connector. What should they do?", "answer": "Remove power safely and do not fly until the electrical malfunction and any resulting damage are inspected and corrected.", "distractors": ["Power-cycle the aircraft, and fly if the smell does not return during the second startup.", "Clean off the soot, and fly if the connector still supplies power during a ground test.", "Replace the circuit fuse, and resume operations without investigating what produced the heat and soot."], "explanation": "Odor, soot, or arcing can indicate a fire and heat hazard that may damage structure, performance, or flight duration.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, conditions 5 and 6", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 243, "category": "Operations & Safety", "difficulty": "Applied", "question": "What does an unexplained change in propulsion-system sound require before the next flight?", "answer": "Inspect the aircraft—especially motors and propellers—for damage, imbalance, or diminished performance.", "distractors": ["Treat the new sound as normal motor break-in as long as the aircraft still powers up.", "Recalibrate the electronic speed controllers and fly without inspecting the motors or propellers.", "Rely on the flight controller to compensate automatically for the source of the changed sound."], "explanation": "A new sound can be the earliest detectable sign of a mechanical problem even when the aircraft still powers up normally.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, condition 7", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 244, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A motor-mount fastener cannot be tightened securely during preflight. What is the correct decision?", "answer": "Replace the fastener that cannot be secured, inspect the affected attachment and structure, and do not fly until structural integrity is confirmed.", "distractors": ["Tighten the damaged fastener beyond the manufacturer's torque limit and fly immediately.", "Apply threadlocker and fly even though the fastener still cannot be tightened securely.", "Reduce payload and airspeed because lighter loading compensates for an insecure motor mount."], "explanation": "FAA guidance says to secure loose hardware and replace fasteners that cannot be secured; loose hardware can cause structural failure or dropped objects.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, condition 11", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 245, "category": "Operations & Safety", "difficulty": "Foundation", "question": "Which measures may a manufacturer use to schedule periodic small-UAS maintenance or component replacement?", "answer": "Flight hours, operating cycles, calendar time, or another published time-in-service limit.", "distractors": ["A manufacturer may schedule maintenance only when a component shows visible damage.", "A manufacturer may schedule maintenance according to the remote pilot's certificate currency.", "A manufacturer may schedule maintenance according to the number of paying clients served."], "explanation": "A component can reach a maintenance limit even when it looks serviceable during a quick visual inspection.", "source": {"label": "FAA AC 107-2A", "reference": "Chapter 7, ¶ 7.2.1 — Scheduled Maintenance", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 246, "category": "Operations & Safety", "difficulty": "Scenario", "question": "The manufacturer issues an unscheduled system-software update to correct a known flight-control problem. May the operator postpone it and fly?", "answer": "No; the problem must be corrected before flight operations resume.", "distractors": ["Yes; the operator may postpone the corrective update until the next annual inspection.", "Yes; the operator may fly in manual mode because software defects affect only automated flight.", "Yes; the operator may ignore the update unless the FAA separately issues an airworthiness directive."], "explanation": "FAA guidance treats a corrective system-software update as unscheduled maintenance when it addresses a safety-related condition.", "source": {"label": "FAA AC 107-2A", "reference": "Chapter 7, ¶ 7.2.2 — Unscheduled Maintenance", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 247, "category": "Operations & Safety", "difficulty": "Applied", "question": "If the manufacturer provides no scheduled maintenance program, what should the operator establish?", "answer": "A documented maintenance protocol that tracks repairs, modifications, replacements, and component time in service.", "distractors": ["The operator should perform no maintenance until a component visibly fails.", "The operator should adopt a generic 100-hour interval without considering the aircraft or component history.", "The operator should track only total aircraft hours and omit repairs, modifications, replacements, and component time."], "explanation": "Consistent records let the operator build evidence-based intervals instead of waiting for visible failure.", "source": {"label": "FAA AC 107-2A", "reference": "Chapter 7, ¶ 7.2.1.1 — operator-developed maintenance protocol", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 248, "category": "Operations & Safety", "difficulty": "Applied", "question": "What should a post-flight review record about aircraft condition and mission risk controls?", "answer": "Equipment malfunctions or anomalies, whether the mitigations worked, unexpected hazards, and any repairs or revisions needed before the next flight.", "distractors": ["The post-flight review should record only flight duration and location, not equipment anomalies or ineffective controls.", "The post-flight review should record only successful mitigations and omit unexpected hazards.", "The crew should defer all anomaly notes until the next preflight instead of recording them in the post-flight review."], "explanation": "A structured review catches developing defects and prevents ineffective controls from being reused without correction.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix E — Post-Flight review", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 249, "category": "Operations & Safety", "difficulty": "Applied", "question": "What is required before a remote-pilot crewmember may have unescorted access to an airport Security Identification Display Area (SIDA)?", "answer": "Airport authorization, required security checks and training, and airport-issued identification displayed under the airport’s access procedures.", "distractors": ["A Remote Pilot Certificate alone authorizes the crew to enter any airport SIDA.", "A visual observer may escort the crew into a SIDA without airport authorization or identification.", "Remaining below 400 feet gives a remote-pilot crew ground access to a SIDA without following airport procedures."], "explanation": "A Remote Pilot Certificate is not a SIDA credential; escorted and unescorted access must follow the airport security program.", "source": {"label": "49 CFR § 1542.205", "reference": "49 CFR § 1542.205 — security of the SIDA", "url": "https://www.ecfr.gov/current/title-49/subtitle-B/chapter-XII/subchapter-C/part-1542/subpart-C/section-1542.205"}},
  {"id": 250, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A client requests a 200-foot-AGL inspection directly over a facility designated as national-security-sensitive. Does staying below 400 feet make the flight permissible?", "answer": "No; designated facility restrictions apply from the ground up to 400 feet AGL unless the operation is specifically authorized.", "distractors": ["Yes; every flight below 400 feet AGL is permissible over a national-security-sensitive facility.", "Yes; a standard LAANC airspace authorization alone overrides designated facility restrictions.", "Yes; the restriction applies only when people are present at the facility during the flight."], "explanation": "Examples can include designated military sites, national landmarks, and certain critical infrastructure; the pilot must check current restrictions for the location.", "source": {"label": "FAA Critical Infrastructure and Public Venues", "reference": "Designated national-security-sensitive facility restrictions", "url": "https://www.faa.gov/uas/critical_infrastructure"}}
];
